window.CC.p.push({n:4,view:"<section class=\"view\" id=\"p4\" hidden style=\"--c:#7a8b00\"><h1><i>4</i>Cardiology</h1><p class=\"lead\">30 sections — pick what you want to read.</p><div class=\"grid\"><h3 class=\"sg\">Part 4A</h3><div class=\"card\" data-u=\"u51\"><button class=\"open\" data-u=\"u51\"><b>Case 1</b><span>Essential (PRIMARY) Hypertension</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Essential+%28PRIMARY%29+Hypertension\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u52\"><button class=\"open\" data-u=\"u52\"><b>Case 2</b><span>Secondary Hypertension &amp; Resistant Hypertension</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Secondary+Hypertension+%26+Resistant+Hypertension\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u53\"><button class=\"open\" data-u=\"u53\"><b>Case 3</b><span>Hypertensive Urgency vs. Hypertensive Emergency</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hypertensive+Urgency+vs.+Hypertensive+Emergency\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u54\"><button class=\"open\" data-u=\"u54\"><b>Case 4</b><span>Chronic Coronary Syndrome (STABLE ANGINA PECTORIS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Chronic+Coronary+Syndrome+%28STABLE+ANGINA+PECTORIS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u55\"><button class=\"open\" data-u=\"u55\"><b>Case 5</b><span>Nste-Acs (UNSTABLE ANGINA &amp; NSTEMI)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Nste-Acs+%28UNSTABLE+ANGINA+%26+NSTEMI%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u56\"><button class=\"open\" data-u=\"u56\"><b>Case 6</b><span>STEMI (ST-ELEVATION MYOCARDIAL INFARCTION)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=STEMI+%28ST-ELEVATION+MYOCARDIAL+INFARCTION%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u57\"><button class=\"open\" data-u=\"u57\"><b>Case 7</b><span>Acute Decompensated Heart Failure (ADHF) &amp; Acute Pulmonary Edema</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Decompensated+Heart+Failure+%28ADHF%29+%26+Acute+Pulmonary+Edema\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u58\"><button class=\"open\" data-u=\"u58\"><b>Case 8</b><span>Chronic Heart Failure with Reduced Ejection Fraction (HFrEF)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Chronic+Heart+Failure+with+Reduced+Ejection+Fraction+%28HFrEF%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u59\"><button class=\"open\" data-u=\"u59\"><b>Case 9</b><span>Heart Failure with Preserved Ejection Fraction (HFpEF)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Heart+Failure+with+Preserved+Ejection+Fraction+%28HFpEF%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u60\"><button class=\"open\" data-u=\"u60\"><b>Case 10</b><span>Mitral Stenosis (MS) — an Egyptian Cardiology Staple</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Mitral+Stenosis+%28MS%29+%E2%80%94+an+Egyptian+Cardiology+Staple\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u61\"><button class=\"open\" data-u=\"u61\"><b>Case 11</b><span>Mitral Regurgitation (MR)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Mitral+Regurgitation+%28MR%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u62\"><button class=\"open\" data-u=\"u62\"><b>Case 12</b><span>Aortic Stenosis (AS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Aortic+Stenosis+%28AS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u63\"><button class=\"open\" data-u=\"u63\"><b>Case 13</b><span>Aortic Regurgitation (AR)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Aortic+Regurgitation+%28AR%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u64\"><button class=\"open\" data-u=\"u64\"><b>Case 14</b><span>Acute Pericarditis, Pericardial Effusion &amp; Cardiac Tamponade</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Pericarditis%2C+Pericardial+Effusion+%26+Cardiac+Tamponade\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u65\"><button class=\"open\" data-u=\"u65\"><b>Case 15</b><span>Infective Endocarditis (IE)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Infective+Endocarditis+%28IE%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><h3 class=\"sg\">Part 4B</h3><div class=\"card\" data-u=\"u66\"><button class=\"open\" data-u=\"u66\"><b>Case 16</b><span>Atrial Fibrillation (AFIB) &amp; Atrial Flutter</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Atrial+Fibrillation+%28AFIB%29+%26+Atrial+Flutter\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u67\"><button class=\"open\" data-u=\"u67\"><b>Case 17</b><span>Supraventricular Tachycardia (PSVT / AVNRT)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Supraventricular+Tachycardia+%28PSVT+%2F+AVNRT%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u68\"><button class=\"open\" data-u=\"u68\"><b>Case 18</b><span>Ventricular Tachycardia (VT) &amp; Ventricular Fibrillation (VF)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Ventricular+Tachycardia+%28VT%29+%26+Ventricular+Fibrillation+%28VF%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u69\"><button class=\"open\" data-u=\"u69\"><b>Case 19</b><span>Bradyarrhythmias &amp; Atrioventricular (AV) Blocks</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Bradyarrhythmias+%26+Atrioventricular+%28AV%29+Blocks\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u70\"><button class=\"open\" data-u=\"u70\"><b>Case 20</b><span>Syncope (DIAGNOSTIC APPROACH)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Syncope+%28DIAGNOSTIC+APPROACH%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u71\"><button class=\"open\" data-u=\"u71\"><b>Case 21</b><span>Acute Rheumatic Fever (ARF) &amp; Chronic Rheumatic Heart Disease (RHD)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Rheumatic+Fever+%28ARF%29+%26+Chronic+Rheumatic+Heart+Disease+%28RHD%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u72\"><button class=\"open\" data-u=\"u72\"><b>Case 22</b><span>Dilated Cardiomyopathy (DCM) &amp; Peripartum Cardiomyopathy (PPCM)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Dilated+Cardiomyopathy+%28DCM%29+%26+Peripartum+Cardiomyopathy+%28PPCM%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u73\"><button class=\"open\" data-u=\"u73\"><b>Case 23</b><span>Hypertrophic Cardiomyopathy (HCM)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hypertrophic+Cardiomyopathy+%28HCM%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u74\"><button class=\"open\" data-u=\"u74\"><b>Case 24</b><span>Acute Myocarditis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Myocarditis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u75\"><button class=\"open\" data-u=\"u75\"><b>Case 25</b><span>Acute Aortic Dissection</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Aortic+Dissection\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u76\"><button class=\"open\" data-u=\"u76\"><b>Case 26</b><span>Peripheral Arterial Disease (PAD) &amp; Acute Limb Ischemia (ALI)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Peripheral+Arterial+Disease+%28PAD%29+%26+Acute+Limb+Ischemia+%28ALI%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u77\"><button class=\"open\" data-u=\"u77\"><b>Case 27</b><span>Pulmonary Hypertension (PH) &amp; COR Pulmonale</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pulmonary+Hypertension+%28PH%29+%26+COR+Pulmonale\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u78\"><button class=\"open\" data-u=\"u78\"><b>Case 28</b><span>Dyslipidemia &amp; Cardiovascular Risk Prevention</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Dyslipidemia+%26+Cardiovascular+Risk+Prevention\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u79\"><button class=\"open\" data-u=\"u79\"><b>Case 29</b><span>Cardiogenic Shock</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cardiogenic+Shock\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u80\"><button class=\"open\" data-u=\"u80\"><b>Case 30</b><span>Cardiac Arrest &amp; Acls Reversible Causes</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cardiac+Arrest+%26+Acls+Reversible+Causes\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div></div></section>",units:"<article class=\"view unit\" id=\"u51\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 1</span><h1>Essential (PRIMARY) Hypertension</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Essential+%28PRIMARY%29+Hypertension\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p><i>Chronic systemic arterial </i><i><b>HTN</b></i><i> (Hypertension) without an identifiable single secondary cause, defined by </i><i><b>ESC/ESH</b></i><i> (European Society of Cardiology) office blood pressure </i><i><b>≥ 140/90 mmHg</b></i><i> (or </i><i><b>ACC/AHA</b></i><i> ≥ 130/80 mmHg) confirmed on ≥ 2 separate visits or via </i><i><b>ABPM</b></i><i> (Ambulatory Blood Pressure Monitoring).</i></p><h3><b>2. Etiology &amp; Risk Factors (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i><b>Non-Modifiable Risk Factors:</b></i><i> Advancing age, family history / polygenic predisposition, male sex (earlier onset).</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i><b>Modifiable Lifestyle &amp; Metabolic Factors:</b></i><i> High dietary sodium intake (very common in Egyptian diet: pickles, salty cheeses), obesity / metabolic syndrome, physical inactivity, smoking, chronic psychological stress, </i><mark class=\"hl lab\"><i><b>OSA</b></i></mark><i> (Obstructive Sleep Apnea).</i></span></p><h3><b>3. Pathophysiology</b></h3><p><i>Multifactorial dysregulation involving </i><i><b>RAAS</b></i><i> (Renin-Angiotensin-Aldosterone System) overactivation, increased sympathetic nervous system tone, endothelial dysfunction, and age-related arterial stiffness, leading to persistently elevated </i><i><b>SVR</b></i><i> (Systemic Vascular Resistance) and/or cardiac output.</i></p><h3><b>4. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><i>Usually </i><i><b>asymptomatic (\"The Silent Killer\")</b></i><i>; discovered incidentally.</i></li>\n<li class=\"l1\"><i>Non-specific symptoms when markedly elevated: Occipital morning headache, dizziness, blurred vision, epistaxis, palpitations.</i></li>\n<li class=\"l1\"><i>Examine for </i><i><b>HMOD</b></i><i> (Hypertension-Mediated Organ Damage): Fundoscopy (hypertensive retinopathy: AV nicking, hemorrhages, papilledema), sustained </i><i><b>PMI</b></i><i> (Point of Maximal Impulse) suggesting </i><i><b>LVH</b></i><i> (Left Ventricular Hypertrophy), </i><i><b>S4 gallop</b></i><i>, carotid/renal bruits.</i></li>\n</ul><h3><b>5. Investigations (Mandatory Baseline Workup)</b></h3><ul>\n<li class=\"l1\"><i><b>Confirm Diagnosis:</b></i><i> Proper seated BP measurement (both arms initially, rest 5 min, proper cuff size) +/- </i><i><b>HBPM</b></i><i> (Home BP Monitoring) or </i><i><b>24-hr ABPM</b></i><i> (rules out White Coat HTN and detects Masked HTN).</i></li>\n<li class=\"l1\"><i><b>Basic Labs:</b></i><i> </i><mark class=\"hl mech\"><i><b>RFTs</b></i></mark><i> (Renal Function Tests) + </i><i><b>eGFR</b></i><i> (Estimated Glomerular Filtration Rate), Serum Electrolytes (</i><i><b>K+</b></i><i>, </i><i><b>Na+</b></i><i>), Fasting Blood Glucose / </i><mark class=\"hl mech\"><i><b>HbA1c</b></i></mark><i> , Fasting Lipid Profile, </i><mark class=\"hl mech\"><i><b>TSH</b></i></mark><i> , Urinalysis + </i><i><b>UACR</b></i><i> (Urine Albumin-to-Creatinine Ratio).</i></li>\n<li class=\"l1\"><i><b>Cardiac Workup:</b></i><i> </i><mark class=\"hl mech\"><i><b>12-Lead ECG</b></i></mark><i> (screen for LVH [Sokolow-Lyon criteria], ischemia, AFib) + </i><mark class=\"hl mech\"><i><b>Echocardiogram</b></i></mark><i> (if murmur, HF symptoms, or ECG LVH).</i></li>\n</ul><h3><b>6. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\"><i>White Coat Hypertension, Masked Hypertension, </i><i><b>Secondary Hypertension</b></i><i> (see Case 2), Pain/Anxiety-induced transient BP elevation.</i></li>\n</ul><h3><b>7. Complications (HMOD)</b></h3><ul>\n<li class=\"l1\"><i><b>Brain:</b></i><i> Ischemic &amp; Hemorrhagic Stroke, Vascular Dementia.</i></li>\n<li class=\"l1\"><i><b>Heart:</b></i><i> </i><i><b>LVH</b></i><i>, </i><mark class=\"hl lab\"><i><b>CAD</b></i></mark><i> (Coronary Artery Disease), </i><mark class=\"hl lab\"><i><b>MI</b></i></mark><i> , </i><i><b>HF</b></i><i> (Heart Failure), </i><mark class=\"hl lab\"><i><b>AFib</b></i></mark><i> (Atrial Fibrillation).</i></li>\n<li class=\"l1\"><i><b>Vessels:</b></i><i> Aortic Dissection, </i><mark class=\"hl lab\"><i><b>PAD</b></i></mark><i> (Peripheral Arterial Disease).</i></li>\n<li class=\"l1\"><i><b>Kidneys &amp; Eyes:</b></i><i> Hypertensive Nephrosclerosis (</i><mark class=\"hl lab\"><i><b> CKD</b></i></mark><i> ), Hypertensive Retinopathy.</i></li>\n</ul><h3><b>8. Treatment</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><i><b>Lifestyle Modifications (Lowers SBP by 10–20 mmHg):</b></i></mark><i> Dietary sodium &lt; 2 g/day (&lt; 5 g salt), </i><i><b>DASH</b></i><i> (Dietary Approaches to Stop Hypertension) diet, weight loss, regular aerobic exercise (150 min/week), smoking cessation.</i></li>\n<li class=\"l1\"><i><b>First-Line Antihypertensive Classes (Target &lt; 130/80 mmHg in most adults if tolerated):</b></i></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i><b>ACE-i</b></i><i> (Angiotensin-Converting Enzyme Inhibitors, e.g., Ramipril, Perindopril, Enalapril) OR </i><mark class=\"hl rx\"><i><b>ARBs</b></i></mark><i> (Angiotensin II Receptor Blockers, e.g., Valsartan, Telmisartan, Candesartan) — especially in Diabetes, CKD/proteinuria, HFrEF, CAD! (NEVER combine ACE-i + ARB!).</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i><b>Dihydropyridine CCBs</b></i><i> (Calcium Channel Blockers, e.g., </i><mark class=\"hl rx\"><i><b>Amlodipine</b></i></mark><i> 5–10 mg, Nifedipine LA) — effective in elderly, isolated systolic HTN, pregnancy (Nifedipine).</i></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><i><b>Thiazide-Like Diuretics</b></i><i> (e.g., </i><i><b>Indapamide</b></i><i>, </i><i><b>Chlorthalidone</b></i><i>, or Hydrochlorothiazide) — great in elderly/salt-sensitive HTN.</i></span></p>\n<ul>\n<li class=\"l1\"><i><b>Modern Strategy (ESC/ESH):</b></i><i> Start most patients on a </i><i><b>Single-Pill Dual Combination</b></i><i> (e.g., </i><mark class=\"hl rx\"><i><b>ACE-i/ARB + CCB</b></i></mark><i> OR </i><mark class=\"hl rx\"><i><b>ACE-i/ARB + Thiazide-like diuretic</b></i></mark><i> ); escalate to </i><mark class=\"hl rx\"><i><b>Triple Combination (ACE-i/ARB + CCB + Diuretic)</b></i></mark><i> ; if still uncontrolled -&gt; add </i><mark class=\"hl rx\"><i><b>Spironolactone</b></i></mark><i> 25 mg!</i></li>\n<li class=\"l1\"><i>Special Population — Pregnancy: </i><mark class=\"hl rx\"><i><b>Labetalol</b></i></mark><i> , </i><i><b>Extended-Release Nifedipine</b></i><i>, or </i><i><b>Methyldopa</b></i><i> (</i><mark class=\"hl rx\"><i><b> ACE-i, ARBs, and Renin inhibitors are STRICTLY CONTRAINDICATED in pregnancy!</b></i></mark><i> ).</i></li>\n</ul><nav class=\"un\"><span></span><button class=\"nv\" data-u=\"u52\">Case 2 →</button></nav></article><article class=\"view unit\" id=\"u52\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 2</span><h1>Secondary Hypertension &amp; Resistant Hypertension</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Secondary+Hypertension+%26+Resistant+Hypertension\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><ul>\n<li class=\"l1\"><i><b>Secondary HTN:</b></i><i> Hypertension caused by an identifiable, potentially curable underlying pathology (~5–10% of HTN patients).</i></li>\n<li class=\"l1\"><i><b>Resistant HTN:</b></i><i> BP remaining </i><i><b>≥ 140/90 mmHg</b></i><i> despite concurrent use of </i><i><b>3 antihypertensive agents at optimal doses, one of which MUST be a diuretic</b></i><i> (after confirming medication adherence and excluding white-coat effect).</i></li>\n</ul><h3><b>2. Etiology of Secondary HTN (Separated by Cause — Mnemonic: \"ABCDE\")</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i><b>A</b></i><i>ldosteronism (</i><i><b>Primary Hyperaldosteronism / Conn’s Syndrome</b></i><i>): #1 endocrine cause; adrenal adenoma or bilateral hyperplasia -&gt; HTN + </i><i><b>unprovoked Hypokalemia</b></i><i> + metabolic alkalosis.</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i><b>B</b></i><i>ruits / </i><i><b>Renovascular HTN</b></i><i> (</i><i><b>Renal Artery Stenosis</b></i><i>):</i></span></p>\n<ul>\n<li class=\"l2\"><i>Young females (&lt; 40): </i><i><b>Fibromuscular Dysplasia</b></i><i> (\"string-of-beads\" renal artery).</i></li>\n<li class=\"l2\"><i>Elderly smokers/atherosclerotic: </i><i><b>Atherosclerotic RAS</b></i><i> -&gt; abdominal bruit, </i><i><b>flash pulmonary edema</b></i><i>, acute creatinine rise (&gt; 30%) after starting ACE-i/ARB!</i></li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><i><b>C</b></i><i>oarcation of Aorta / </i><i><b>C</b></i><i>ushing’s Syndrome / </i><i><b>C</b></i><i>hronic Kidney Disease (</i><mark class=\"hl lab\"><i><b> CKD — #1 overall secondary cause!</b></i></mark><i> ):</i></span></p>\n<ul>\n<li class=\"l2\"><i>Coarctation: Young patient with </i><i><b>upper limb HTN + weak/delayed femoral pulses (radio-femoral delay)</b></i><i> + rib notching on CXR.</i></li>\n</ul>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><i><b>D</b></i><i>rugs &amp; Diet: </i><mark class=\"hl rx\"><i><b>NSAIDs</b></i></mark><i> (very common!), </i><i><b>OCPs</b></i><i> (Oral Contraceptive Pills), Corticosteroids, Decongestants (Pseudoephedrine), Licorice (Erk-Sous — classic Egyptian Ramadan drink causing hypokalemic pseudohyperaldosteronism!), Cyclosporine, Erythropoietin.</i></span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><i><b>E</b></i><i>ndocrine (</i><i><b>Pheochromocytoma</b></i><i>, Hyper/Hypothyroidism) &amp; </i><mark class=\"hl lab\"><i><b>OSA</b></i></mark><i> (Obstructive Sleep Apnea — #1 cause of resistant HTN in obese snoring males!).</i></span></p><h3><b>3. When to Suspect Secondary HTN (\"Red Flags\")</b></h3><ul>\n<li class=\"l1\"><i>Onset </i><i><b>&lt; 30 years</b></i><i> (non-obese, no family history) or sudden worsening in </i><i><b>&gt; 55 years</b></i><i>.</i></li>\n<li class=\"l1\"><i><b>Resistant HTN</b></i><i> or malignant/hypertensive emergency.</i></li>\n<li class=\"l1\"><i>Unprovoked </i><i><b>hypokalemia</b></i><i> (Conn’s syndrome) or paroxysmal </i><i><b>headache + sweating + palpitations</b></i><i> (Pheochromocytoma).</i></li>\n</ul><h3><b>4. Targeted Investigations</b></h3><ul>\n<li class=\"l1\"><i><b>Renal Parenchymal:</b></i><i> RFTs, Urinalysis, Renal Ultrasound.</i></li>\n<li class=\"l1\"><i><b>Primary Aldosteronism:</b></i><i> Plasma </i><i><b>Aldosterone-to-Renin Ratio (ARR)</b></i><i> (high aldosterone, suppressed renin) -&gt; Adrenal CT.</i></li>\n<li class=\"l1\"><i><b>Renal Artery Stenosis:</b></i><i> Renal Artery </i><mark class=\"hl mech\"><i><b>Doppler Ultrasound</b></i></mark><i> , </i><i><b>CTA</b></i><i> (CT Angiography), or </i><i><b>MRA</b></i><i>.</i></li>\n<li class=\"l1\"><i><b>Pheochromocytoma:</b></i><i> 24-hour urine or </i><i><b>Plasma Free Metanephrines</b></i><i> -&gt; Adrenal CT/MRI (Never biopsy an adrenal mass without ruling out pheochromocytoma first!)</i></li>\n<li class=\"l1\"><mark class=\"hl lab\"><i><b>OSA:</b></i></mark><i> Polysomnography (Sleep Study).</i></li>\n</ul><h3><b>5. Treatment</b></h3><ul>\n<li class=\"l1\"><i>Treat underlying cause (e.g., </i><mark class=\"hl rx\"><i><b>Spironolactone/Eplerenone</b></i></mark><i> or adrenalectomy for Conn’s; </i><i><b>Alpha-blocker [Phenoxybenzamine/Doxazosin] FIRST, then Beta-blocker</b></i><i> before surgery for Pheochromocytoma; </i><i><b>CPAP</b></i><i> for OSA; Renal angioplasty for Fibromuscular Dysplasia).</i></li>\n<li class=\"l1\"><i>For </i><i><b>Resistant HTN:</b></i><i> Verify adherence, stop NSAIDs/Erk-Sous, optimize diuretic (switch HCTZ to Chlorthalidone/Indapamide, or Loop diuretic if eGFR &lt; 30), and add </i><mark class=\"hl rx\"><i><b>Spironolactone</b></i></mark><i> (4th-line drug of choice!).</i></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u51\">← Case 1</button><button class=\"nv\" data-u=\"u53\">Case 3 →</button></nav></article><article class=\"view unit\" id=\"u53\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 3</span><h1>Hypertensive Urgency vs. Hypertensive Emergency</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hypertensive+Urgency+vs.+Hypertensive+Emergency\">🔍 Search on Google</a></header><h3><b>1. Definition (Crucial Distinction: BP ≥ 180/120 mmHg — Look for End-Organ Damage, NOT just the number!)</b></h3><ul>\n<li class=\"l1\"><i><b>Hypertensive Urgency:</b></i><i> Severe BP elevation (</i><i><b>≥ 180/120 mmHg</b></i><i>) with </i><i><b>NO acute end-organ damage</b></i><i>.</i></li>\n<li class=\"l1\"><i><b>Hypertensive Emergency:</b></i><i> Severe BP elevation (</i><i><b>≥ 180/120 mmHg</b></i><i>) </i><i><b>WITH acute, ongoing end-organ damage</b></i><i> (life-threatening!).</i></li>\n</ul><h3><b>2. Acute End-Organ Damage Manifestations (Separated by Organ)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i><b>Brain:</b></i><i> Hypertensive encephalopathy (headache, confusion, seizures, cortical blindness), Intracerebral Hemorrhage (</i><i><b>ICH</b></i><i>), Acute Ischemic Stroke, </i><mark class=\"hl lab\"><i><b>SAH</b></i></mark><i> .</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i><b>Heart:</b></i><i> </i><mark class=\"hl lab\"><i><b>ACS / Acute MI</b></i></mark><i> , Acute Cardiogenic Pulmonary Edema.</i></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><i><b>Aorta:</b></i><i> </i><i><b>Acute Aortic Dissection</b></i><i>.</i></span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><i><b>Kidneys:</b></i><i> </i><mark class=\"hl lab\"><i><b>AKI</b></i></mark><i> (hematuria, oliguria, rising creatinine).</i></span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><i><b>Eyes &amp; Pregnancy:</b></i><i> Malignant Hypertension (Grade III/IV retinopathy: flame hemorrhages, cotton-wool spots, </i><i><b>papilledema</b></i><i>), </i><mark class=\"hl lab\"><i><b>Eclampsia / Severe Preeclampsia</b></i></mark><i> .</i></span></p><h3><b>3. Investigations (Rapid ER Triage)</b></h3><ul>\n<li class=\"l1\"><i><b>Immediate:</b></i><i> BP in both arms, Neurological exam, </i><i><b>Fundoscopy</b></i><i>, </i><mark class=\"hl mech\"><i><b>ECG</b></i></mark><i> (ischemia), </i><mark class=\"hl mech\"><i><b>Cardiac Troponin</b></i></mark><i> , </i><mark class=\"hl mech\"><i><b>RFTs + Electrolytes</b></i></mark><i> , </i><mark class=\"hl mech\"><i><b>Urinalysis</b></i></mark><i> (protein/RBCs), </i><mark class=\"hl mech\"><i><b>CXR </b></i></mark><i>(pulmonary edema/widened mediastinum), </i><i><b>CT Brain</b></i><i> (if neuro symptoms), </i><mark class=\"hl mech\"><i><b>β-hCG</b></i></mark><i> (if female of childbearing age).</i></li>\n</ul><h3><b>4. Treatment (DO NOT DROP BP TOO FAST IN MOST CASES!)</b></h3><ul>\n<li class=\"l1\"><i><b>Hypertensive Urgency (NO Organ Damage):</b></i></li>\n<li class=\"l2\"><i><b>NO IV drugs and NO sublingual Nifedipine!</b></i><i> (Sublingual Nifedipine causes unpredictable precipitous BP drops leading to stroke/MI!).</i></li>\n<li class=\"l2\"><i>Rest patient in quiet room for 30 minutes, resume/adjust </i><mark class=\"hl mech\"><i><b>oral</b></i></mark><i> antihypertensives (e.g., oral Captopril, Amlodipine, or Clonidine) to reduce BP gradually over </i><i><b>24– 48 hours</b></i><i>; outpatient follow-up within 1–3 days.</i></li>\n<li class=\"l1\"><i><b>Hypertensive Emergency (WITH Organ Damage -&gt; Admit to ICU + Arterial Line + IV Infusions):</b></i></li>\n<li class=\"l2\"><i>General Rule: Reduce </i><i><b>MAP</b></i><i> (Mean Arterial Pressure) by </i><i><b>max 20–25% over the first 1 hour</b></i><i>, then to ~160/100 mmHg over 2–6 hours (excessive rapid drop causes watershed cerebral/renal ischemia!).</i></li>\n<li class=\"l2\"><i>Preferred IV Drugs: </i><mark class=\"hl rx\"><i><b>IV Labetalol</b></i></mark><i> , </i><i><b>IV Nicardipine</b></i><i>, </i><mark class=\"hl rx\"><i><b>IV Nitroglycerin</b></i></mark><i> (preferred in Acute Pulmonary Edema / ACS), </i><i><b>IV Esmolol</b></i><i>, </i><i><b>IV Sodium Nitroprusside</b></i><i>.</i></li>\n<li class=\"l2\"><i>CRITICAL EXCEPTIONS TO THE 25% RULE:</i></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl lab\"><i><b>Acute Aortic Dissection:</b></i></mark><i> Drop </i><i><b>HR &lt; 60 bpm FIRST</b></i><i> (IV Esmolol/Labetalol) AND drop </i><mark class=\"hl lab\"><i><b>SBP to 100–120 mmHg within 20 minutes</b></i></mark><i> !</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i><b>Acute Ischemic Stroke:</b></i><i> </i><i><b>Do NOT lower BP</b></i><i> unless </i><i><b>&gt; 220/120 mmHg</b></i><i> (or </i><i><b>&gt; 185/110 mmHg</b></i><i> if candidate for </i><mark class=\"hl rx\"><i><b>tPA</b></i></mark><i> thrombolysis)!</i></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl lab\"><i><b>Severe Preeclampsia / Eclampsia:</b></i></mark><i> </i><mark class=\"hl rx\"><i><b>IV Labetalol</b></i></mark><i> or </i><mark class=\"hl rx\"><i><b>IV Hydralazine</b></i></mark><i> (or oral Nifedipine) + </i><mark class=\"hl rx\"><i><b>IV Magnesium Sulfate</b></i></mark><i> !</i></span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u52\">← Case 2</button><button class=\"nv\" data-u=\"u54\">Case 4 →</button></nav></article><article class=\"view unit\" id=\"u54\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 4</span><h1>Chronic Coronary Syndrome (STABLE ANGINA PECTORIS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Chronic+Coronary+Syndrome+%28STABLE+ANGINA+PECTORIS%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p class=\"muted\"><i>Predictable, transient myocardial ischemia occurring when myocardial oxygen demand exceeds supply, causing chest discomfort that is reproducible with exertion/stress and relieved by rest or nitroglycerin.</i></p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl dx\"><i><b>Fixed Coronary Atherosclerosis (&gt; 90%):</b></i></mark><i> ≥ 70% luminal narrowing of an epicardial coronary artery (or ≥ 50% of Left Main).</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i><b>Non-Atherosclerotic / Supply-Demand Causes:</b></i><i> Severe </i><i><b>Aortic Stenosis</b></i><i>, </i><mark class=\"hl lab\"><i><b>HCM</b></i></mark><i> , severe Anemia, Thyrotoxicosis, </i><i><b>Prinzmetal (Vasospastic) Angina</b></i><i> (occurs at rest, younger smokers, transient ST elevation).</i></span></p><h3><b>3. Clinical Picture (3 Classic Features of Typical Angina)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i>Constricting/squeezing substernal chest discomfort (may radiate to left arm, neck, jaw, or epigastrium — </i><i><b>Levine’s sign</b></i><i>: clenched fist over sternum).</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i>Provoked by physical exertion, emotional stress, cold weather, or heavy meals.</i></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><i>Relieved within </i><i><b>2–5 minutes</b></i><i> by </i><i><b>rest</b></i><i> or </i><mark class=\"hl rx\"><i><b>sublingual Nitroglycerin</b></i></mark><i> .</i></span></p>\n<p><i>(Note: Diabetic patients, elderly, and women frequently present with </i><i><b>anginal equivalents</b></i><i> like unexplained exertional dyspnea, fatigue, or diaphoresis without chest pain!)</i></p><h3><b>4. Investigations</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><i><b>Resting 12-Lead ECG:</b></i></mark><i> Often </i><i><b>NORMAL</b></i><i> between attacks (may show Q waves of old MI or ST-T changes).</i></li>\n<li class=\"l1\"><i><b>Labs:</b></i><i> </i><mark class=\"hl mech\"><i><b>CBC</b></i></mark><i> (rule out anemia), </i><mark class=\"hl mech\"><i><b>HbA1c</b></i></mark><i> , Lipid Profile, </i><mark class=\"hl mech\"><i><b>RFTs</b></i></mark><i> , </i><mark class=\"hl mech\"><i><b>TSH</b></i></mark><i> , Troponin (if any concern for unstable angina).</i></li>\n<li class=\"l1\"><mark class=\"hl mech\"><i><b>Echocardiogram:</b></i></mark><i> Assess </i><i><b>LVEF</b></i><i> (Left Ventricular Ejection Fraction), wall motion abnormalities, and valvular disease.</i></li>\n<li class=\"l1\"><i><b>Ischemia / Anatomic Testing (Based on Pre-Test Probability):</b></i></li>\n<li class=\"l2\"><mark class=\"hl mech\"><i><b>Exercise Stress ECG</b></i></mark><i> (if normal baseline ECG &amp; able to exercise).</i></li>\n<li class=\"l2\"><mark class=\"hl mech\"><i><b>Stress Echocardiography</b></i></mark><i> or </i><i><b>Myocardial Perfusion Scan (SPECT)</b></i><i> (if baseline ECG abnormal e.g., </i><i><b>LBBB</b></i><i> [Left Bundle Branch Block] or unable to exercise -&gt; pharmacological stress with Dobutamine/Adenosine).</i></li>\n<li class=\"l2\"><mark class=\"hl mech\"><i><b>Coronary CT Angiography (CCTA):</b></i></mark><i> High negative predictive value in low-to-intermediate risk patients.</i></li>\n<li class=\"l2\"><i><b>Invasive Coronary Angiography:</b></i><i> Gold standard (for severe refractory angina, high-risk stress test, or reduced LVEF).</i></li>\n</ul><h3><b>5. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><i><b>ACS</b></i></mark><i> (Unstable Angina/NSTEMI), </i><mark class=\"hl lab\"><i><b>GERD</b></i></mark><i> / Esophageal spasm, Musculoskeletal pain (Costochondritis — reproducible on palpation!), Pericarditis, </i><mark class=\"hl lab\"><i><b>PE</b></i></mark><i> , Panic attack.</i></li>\n</ul><h3><b>6. Treatment (ABCDE — Symptom Relief + Prognostic Mortality Reduction)</b></h3><ul>\n<li class=\"l1\"><i><b>Immediate Angina Relief:</b></i><i> </i><mark class=\"hl rx\"><i><b>Sublingual Nitroglycerin (GTN)</b></i></mark><i> 0.4–0.5 mg PRN (sit down before taking to prevent syncope; if pain persists &gt; 15 min despite 3 doses 5 min apart -&gt; </i><mark class=\"hl lab\"><i><b>CALL EMERGENCY / ER for ACS!</b></i></mark><i> ).</i></li>\n<li class=\"l1\"><i><b>Anti-Ischemic Maintenance:</b></i></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i><b>First-Line:</b></i><i> </i><i><b>Beta-blocker</b></i><i> (Bisoprolol, Metoprolol, Carvedilol — target resting HR 55–60 bpm) and/or </i><i><b>CCB</b></i><i> (Amlodipine; or Diltiazem/Verapamil if BB contraindicated — never combine Verapamil/Diltiazem with Beta-blocker!).</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i><b>Second-Line:</b></i><i> </i><mark class=\"hl rx\"><i><b>Long-Acting Nitrates</b></i></mark><i> (Isosorbide Mononitrate — must maintain an </i><i><b>8–12 hour nitrate-free interval</b></i><i> daily to prevent tolerance!), </i><i><b>Ivabradine</b></i><i>, </i><i><b>Ranolazine</b></i><i>, or </i><i><b>Trimetazidine</b></i><i>.</i></span></p>\n<ul>\n<li class=\"l1\"><i><b>Prognostic / Mortality-Reducing Therapy (Mandatory for ALL CAD Patients!):</b></i></li>\n<li class=\"l2\"><mark class=\"hl rx\"><i><b>Aspirin</b></i></mark><i> 75–100 mg daily lifelong (or </i><mark class=\"hl rx\"><i><b>Clopidogrel</b></i></mark><i> 75 mg if aspirin-intolerant).</i></li>\n<li class=\"l2\"><mark class=\"hl rx\"><i><b>High-Intensity Statin</b></i></mark><i> (Atorvastatin 40–80 mg or Rosuvastatin 20–40 mg daily — target </i><i><b>LDL &lt; 55 mg/dL</b></i><i> per ESC!).</i></li>\n<li class=\"l2\"><mark class=\"hl rx\"><i><b>ACE-i / ARB</b></i></mark><i> (especially if HTN, Diabetes, CKD, or LVEF ≤ 40%).</i></li>\n<li class=\"l2\"><mark class=\"hl mech\"><i><b>Revascularization (PCI/Stent or CABG [Coronary Artery Bypass Grafting]):</b></i></mark><i> For Left Main disease (&gt; 50%), 3-vessel disease (especially diabetics/low EF -&gt; </i><mark class=\"hl mech\"><i><b>CABG</b></i></mark><i> superior), or refractory angina.</i></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u53\">← Case 3</button><button class=\"nv\" data-u=\"u55\">Case 5 →</button></nav></article><article class=\"view unit\" id=\"u55\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 5</span><h1>Nste-Acs (UNSTABLE ANGINA &amp; NSTEMI)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Nste-Acs+%28UNSTABLE+ANGINA+%26+NSTEMI%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p><mark class=\"hl lab\"><i><b>ACS</b></i></mark><i> (Acute Coronary Syndrome) without persistent ST-segment elevation on ECG, resulting from acute atherosclerotic plaque rupture/erosion and </i><i><b>non-occlusive (sub-total) coronary thrombosis</b></i><i>.</i></p>\n<ul>\n<li class=\"l1\"><i><b>Unstable Angina (UA):</b></i><i> Myocardial ischemia at rest/minimal exertion </i><i><b>WITHOUT</b></i><i> troponin elevation.</i></li>\n<li class=\"l1\"><mark class=\"hl lab\"><i><b>NSTEMI</b></i></mark><i> (Non-ST-Elevation Myocardial Infarction): Myocardial necrosis </i><mark class=\"hl mech\"><i><b>WITH elevated Cardiac Troponin</b></i></mark><i> (&gt; 99th percentile URL).</i></li>\n</ul><h3><b>2. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><i>New-onset severe angina, crescendo angina (more frequent, severe, or lower threshold), or </i><i><b>rest angina lasting &gt; 20 minutes</b></i><i> + diaphoresis, dyspnea, nausea.</i></li>\n<li class=\"l1\"><i>May have rales (pulmonary congestion), </i><i><b>S3/S4</b></i><i>, or new mitral regurgitation murmur (papillary muscle ischemia).</i></li>\n</ul><h3><b>3. Investigations</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><i><b>12-Lead ECG within 10 minutes:</b></i></mark><i> May show </i><i><b>ST-segment depression</b></i><i>, </i><i><b>T-wave inversion</b></i><i>, transient ST elevation, OR may be completely </i><i><b>normal</b></i><i>! (Repeat serial ECGs every 15–30 min if pain continues).</i></li>\n<li class=\"l1\"><mark class=\"hl mech\"><i><b>High-Sensitivity Cardiac Troponin (hs-cTn):</b></i></mark><i> Draw at </i><i><b>0 hours</b></i><i> and repeat at </i><i><b>1–3 hours</b></i><i> (rises and falls in NSTEMI; normal in UA).</i></li>\n<li class=\"l1\"><i><b>Risk Stratification:</b></i><i> </i><i><b>GRACE Score</b></i><i> &amp; </i><i><b>TIMI Score</b></i><i> (determines timing of coronary angiography).</i></li>\n<li class=\"l1\"><mark class=\"hl mech\"><i><b>Bedside Echocardiogram:</b></i></mark><i> Assess wall motion &amp; LVEF.</i></li>\n</ul><h3><b>4. Treatment (Immediate Antithrombotic + Anti-Ischemic + Invasive Strategy)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i><b>Immediate Stabilization:</b></i><i> Oxygen ONLY if </i><mark class=\"hl mech\"><i><b>SpO2 &lt; 90%</b></i></mark><i> , IV access, continuous cardiac monitoring.</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i><b>DAPT (Dual Antiplatelet Therapy):</b></i></span></p>\n<ul>\n<li class=\"l2\"><mark class=\"hl rx\"><i><b>Aspirin 300 mg chewed</b></i></mark><i> stat (then 75–100 mg OD lifelong).</i></li>\n<li class=\"l2\"><i><b>PLUS a P2Y12 Inhibitor:</b></i><i> </i><mark class=\"hl rx\"><i><b>Ticagrelor 180 mg load</b></i></mark><i> (then 90 mg BID — preferred if no high bleeding risk) OR </i><mark class=\"hl rx\"><i><b>Clopidogrel 300–600 mg load</b></i></mark><i> (then 75 mg OD — widely used in Egypt, especially if high bleeding risk or fibrinolysis/oral anticoagulation).</i></li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><i><b>Anticoagulation (Start immediately alongside DAPT):</b></i></span></p>\n<ul>\n<li class=\"l2\"><mark class=\"hl rx\"><i><b>Enoxaparin (LMWH)</b></i></mark><i> 1 mg/kg </i><i><b>SC q12h</b></i><i>, </i><i><b>Fondaparinux</b></i><i> 2.5 mg SC OD (lowest bleeding risk), or </i><mark class=\"hl rx\"><i><b>IV UFH</b></i></mark><i> (Unfractionated Heparin).</i></li>\n</ul>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><i><b>Anti-Ischemic &amp; Secondary Prevention:</b></i></span></p>\n<ul>\n<li class=\"l2\"><mark class=\"hl rx\"><i><b>IV/Sublingual Nitroglycerin</b></i></mark><i> for ongoing pain (CONTRAINDICATED if SBP &lt; 90 mmHg, Right Ventricular MI, or PDE-5 inhibitor [Sildenafil/Tadalafil] use within 24–48 hrs!).</i></li>\n<li class=\"l2\"><i><b>Beta-blocker</b></i><i> within 24 hours (ONLY if no heart failure, shock, bradycardia, or heart block!).</i></li>\n<li class=\"l2\"><mark class=\"hl rx\"><i><b>High-Intensity Statin</b></i></mark><i> immediately (Atorvastatin 80 mg or Rosuvastatin 40 mg).</i></li>\n</ul>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><i><b>Coronary Angiography &amp; PCI Timing:</b></i></span></p>\n<ul>\n<li class=\"l2\"><i>Immediate (&lt; 2 hrs): Refractory pain, hemodynamic instability/cardiogenic shock, life-threatening arrhythmias, acute HF.</i></li>\n<li class=\"l2\"><i>Early (&lt; 24 hrs): Elevated troponin (NSTEMI), dynamic ST changes, GRACE score &gt; 140.</i></li>\n<li class=\"l2\"><i>CRITICAL CONTRAINDICATION: </i><mark class=\"hl lab\"><i><b>NEVER give Fibrinolytics (Streptokinase/Alteplase) in NSTEMI or Unstable Angina — it INCREASES mortality!</b></i></mark></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u54\">← Case 4</button><button class=\"nv\" data-u=\"u56\">Case 6 →</button></nav></article><article class=\"view unit\" id=\"u56\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 6</span><h1>STEMI (ST-ELEVATION MYOCARDIAL INFARCTION)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=STEMI+%28ST-ELEVATION+MYOCARDIAL+INFARCTION%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p><i>Acute </i><i><b>transmural myocardial necrosis</b></i><i> caused by </i><i><b>complete, persistent coronary artery occlusion</b></i><i> (usually plaque rupture + occlusive fibrin-rich thrombus). </i><i><b>\"Time is Muscle!\"</b></i></p><h3><b>2. ECG Diagnostic Criteria (Mandatory Localization!)</b></h3><p><i>New </i><i><b>ST-segment elevation at the J-point</b></i><i> in </i><i><b>≥ 2 contiguous leads</b></i><i>:</i></p>\n<ul>\n<li class=\"l1\"><i><b>≥ 1 mm</b></i><i> in all leads EXCEPT V2–V3 (in V2–V3: ≥ 2 mm in men ≥ 40 yrs, ≥ 2.5 mm in men &lt; 40 yrs, ≥ 1.5 mm in women).</i></li>\n<li class=\"l1\"><i>OR </i><i><b>New/presumed new LBBB</b></i><i> with </i><i><b>Sgarbossa criteria</b></i><i> (or Posterior MI: ST depression in V1–V3 with tall R waves -&gt; confirm ST elevation in </i><i><b>V7–V9</b></i><i>!).</i></li>\n</ul><table class=\"t \"><tr><td><p class=\"muted\"><i><b>ECG Leads with ST Elevation</b></i></p></td><td><p class=\"muted\"><i><b>Wall Involved</b></i></p></td><td><p class=\"muted\"><i><b>Culprit Coronary Artery</b></i></p></td><td><p class=\"muted\"><i><b>Key Specific Risk</b></i></p></td></tr><tr><td><p class=\"muted\"><i><b>V1 – V4</b></i></p></td><td><p class=\"muted\"><i>Anterior / Anteroseptal</i></p></td><td><p><i><b>LAD</b></i><i> (Left Anterior Descending)</i></p></td><td><p class=\"muted\"><i>Cardiogenic shock, LV aneurysm, LBBB</i></p></td></tr><tr><td><p class=\"muted\"><i><b>I, aVL, V5 – V6</b></i></p></td><td><p class=\"muted\"><i>Lateral</i></p></td><td><p><i><b>LCx</b></i><i> (Left Circumflex)</i></p></td><td></td></tr><tr><td><p class=\"muted\"><i><b>II, III, aVF</b></i></p></td><td><p class=\"muted\"><i><b>Inferior</b></i></p></td><td><p><i><b>RCA</b></i><i> (Right Coronary Artery — 80%) or LCx</i></p></td><td><p><i><b>AV Block</b></i><i> &amp; </i><i><b>Right Ventricular MI</b></i><i>! (Always do </i><i><b>V4R</b></i><i> lead in Inferior STEMI!)</i></p></td></tr><tr><td><p class=\"muted\"><i><b>V1–V3 ST Depression + Tall R</b></i></p></td><td><p class=\"muted\"><i>Posterior</i></p></td><td><p class=\"muted\"><i>LCx or RCA</i></p></td><td><p class=\"muted\"><i>Confirm with posterior leads V7–V9</i></p></td></tr></table><h3><b>3. Clinical Picture &amp; Complications</b></h3><ul>\n<li class=\"l1\"><i>Severe crushing retrosternal chest pain </i><i><b>&gt; 20–30 minutes</b></i><i> (unrelieved by rest/nitrates), diaphoresis, impending sense of doom, nausea/vomiting (common in Inferior MI due to vagal stimulation).</i></li>\n<li class=\"l1\"><i><b>Major Complications (Mnemonic: \"DR. PUMP\"):</b></i></li>\n<li class=\"l2\"><i><b>D</b></i><i>eath / </i><i><b>D</b></i><i>ysrhythmias (</i><i><b>VF</b></i><i> = #1 cause of early pre-hospital death! </i><i><b>Complete Heart Block</b></i><i> in inferior MI).</i></li>\n<li class=\"l2\"><i><b>R</b></i><i>upture (Free wall rupture -&gt; cardiac tamponade; </i><i><b>Papillary muscle rupture</b></i><i> -&gt; acute severe </i><i><b>MR</b></i><i>; </i><i><b>Ventricular Septal Rupture</b></i><i> -&gt; new holosystolic murmur + shock — all peak Day 3–7!).</i></li>\n<li class=\"l2\"><i><b>P</b></i><i>ericarditis (Early post-MI vs. Late autoimmune </i><i><b>Dressler’s Syndrome</b></i><i> weeks later).</i></li>\n<li class=\"l2\"><i><b>U</b></i><i>nstable pump (</i><i><b>Cardiogenic Shock</b></i><i>, Acute Heart Failure).</i></li>\n<li class=\"l2\"><i><b>M</b></i><i>ural thrombus (LV apex -&gt; systemic stroke/emboli).</i></li>\n<li class=\"l2\"><i><b>P</b></i><i>seudo/True </i><i><b>LV Aneurysm</b></i><i> (persistent ST elevation weeks post-MI).</i></li>\n</ul><h3><b>4. Treatment (REPERFUSION IS EVERYTHING — Do NOT Wait for Troponin!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i><b>Immediate Medical Therapy:</b></i></span></p>\n<ul>\n<li class=\"l2\"><mark class=\"hl rx\"><i><b>Aspirin 300 mg chewed</b></i></mark><i> + </i><i><b>P2Y12 Inhibitor</b></i><i> (</i><mark class=\"hl rx\"><i><b> Ticagrelor 180 mg</b></i></mark><i> or </i><i><b>Prasugrel 60 mg</b></i><i> for Primary PCI; </i><mark class=\"hl rx\"><i><b>Clopidogrel 300 mg</b></i></mark><i> [75 mg if &gt; 75 yrs] if Fibrinolysis) + </i><i><b>Anticoagulant</b></i><i> (</i><mark class=\"hl rx\"><i><b> UFH</b></i></mark><i> or </i><mark class=\"hl rx\"><i><b>Enoxaparin</b></i></mark><i> ) + High-Intensity </i><mark class=\"hl rx\"><i><b>Statin</b></i></mark><i> .</i></li>\n<li class=\"l2\"><i>Caution in Inferior/RV STEMI (ST elevation in V4R + clear lungs + hypotension + JVD): </i><mark class=\"hl rx\"><i><b>AVOID Nitrates and Diuretics</b></i></mark><i> (they crash preload -&gt; severe shock!); treat hypotension with </i><mark class=\"hl rx\"><i><b>IV Normal Saline boluses</b></i></mark><i> !</i></li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i><b>Emergent Reperfusion Strategy:</b></i></span></p>\n<ul>\n<li class=\"l2\"><i><b>Primary PCI (Gold Standard):</b></i><i> Perform if Door-to-Balloon (or first medical contact-to-wire) time </i><i><b>≤ 90–120 minutes</b></i><i>.</i></li>\n<li class=\"l2\"><mark class=\"hl rx\"><i><b>Fibrinolysis / Thrombolysis</b></i></mark><i> (e.g., </i><mark class=\"hl rx\"><i><b>Tenecteplase, Alteplase, or Streptokinase</b></i></mark><i> — still frequently used in Egyptian hospitals without 24/7 cath labs!): Give within </i><i><b>30 minutes</b></i><i> of arrival if Primary PCI cannot be achieved within </i><i><b>120 minutes</b></i><i> AND symptom onset is </i><i><b>&lt; 12 hours</b></i><i> (check contraindications: prior hemorrhagic stroke, ischemic stroke &lt; 3 mos, active bleed, aortic dissection, severe uncontrolled HTN &gt; 180/110!).</i></li>\n<li class=\"l2\"><i>Post-Fibrinolysis: Transfer to a PCI center within </i><i><b>2–24 hours</b></i><i> (Pharmaco-invasive strategy) or immediately for </i><i><b>Rescue PCI</b></i><i> if ST segments fail to resolve by &gt; 50% at 60–90 min!</i></li>\n</ul>\n<p><i>[Image Reference Suggestion]: Classic </i><mark class=\"hl lab\"><i><b>12-Lead ECG showing Anterior STEMI (\"Tombstone\" ST elevation in V1–V4)</b></i></mark><i> + diagram of </i><i><b>Coronary Artery Territories</b></i><i>.</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u55\">← Case 5</button><button class=\"nv\" data-u=\"u57\">Case 7 →</button></nav></article><article class=\"view unit\" id=\"u57\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 7</span><h1>Acute Decompensated Heart Failure (ADHF) &amp; Acute Pulmonary Edema</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Decompensated+Heart+Failure+%28ADHF%29+%26+Acute+Pulmonary+Edema\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p><i>Rapid onset or worsening of signs and symptoms of </i><i><b>HF</b></i><i> (Heart Failure) requiring urgent therapy, most dramatically presenting as </i><i><b>Acute Cardiogenic Pulmonary Edema </b></i><i>(\"flash pulmonary edema\").</i></p><h3><b>2. Precipitating Factors (Separated — Mnemonic: \"FAILURE\")</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i><b>F</b></i><i>orgotten medications (non-compliance) or </i><i><b>F</b></i><i>luid/Salt excess.</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i><b>A</b></i><i>rrhythmias (new rapid </i><mark class=\"hl lab\"><i><b>AFib</b></i></mark><i> , VT, bradycardia).</i></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><i><b>I</b></i><i>schemia / Acute </i><mark class=\"hl lab\"><i><b>MI</b></i></mark><i> .</i></span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><i><b>L</b></i><i>oading (</i><i><b>Hypertensive Crisis</b></i><i>, Pregnancy, Anemia, Thyrotoxicosis).</i></span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><i><b>U</b></i><i>nneeded drugs (</i><mark class=\"hl rx\"><i><b> NSAIDs</b></i></mark><i> , Verapamil/Diltiazem, Steroids, Thiazolidinediones).</i></span></p>\n<p class=\"num\"><span class=\"n\">6.</span><span class=\"nt\"><i><b>R</b></i><i>enal failure (</i><mark class=\"hl lab\"><i><b> AKI/CKD</b></i></mark><i> ) or </i><i><b>P</b></i><i>ulmonary </i><i><b>E</b></i><i>mbolism (</i><mark class=\"hl lab\"><i><b> PE</b></i></mark><i> ).</i></span></p>\n<p class=\"num\"><span class=\"n\">7.</span><span class=\"nt\"><i><b>E</b></i><i>ndocarditis / </i><i><b>I</b></i><i>nfection (Pneumonia, Sepsis).</i></span></p><h3><b>3. Clinical Picture (\"Wet\" vs. \"Dry\" &amp; \"Warm\" vs. \"Cold\")</b></h3><ul>\n<li class=\"l1\"><i>Severe dyspnea, orthopnea, </i><i><b>PND</b></i><i>, tachypnea, anxiety, coughing up </i><i><b>pink frothy sputum</b></i><i>.</i></li>\n<li class=\"l1\"><i>Bilateral inspiratory </i><i><b>basal crackles/rales</b></i><i> (extending up the lung fields), </i><i><b>S3 gallop</b></i><i>, </i><i><b>JVD</b></i><i>, hepatomegaly, peripheral pitting edema.</i></li>\n<li class=\"l1\"><i><b>Cold &amp; Wet (Cardiogenic Shock):</b></i><i> Hypotension (SBP &lt; 90), cool clammy extremities, oliguria, confusion.</i></li>\n</ul><h3><b>4. Investigations</b></h3><ul>\n<li class=\"l1\"><i><b>Immediate:</b></i><i> </i><mark class=\"hl mech\"><i><b>ECG</b></i></mark><i> (rule out STEMI/AFib), </i><mark class=\"hl mech\"><i><b>CXR</b></i></mark><i> (</i><i><b>ABCDE</b></i><i>: </i><i><b>A</b></i><i>lveolar edema [\"bat-wing\"], Kerley </i><i><b>B</b></i><i> lines, </i><i><b>C</b></i><i>ardiomegaly, </i><i><b>D</b></i><i>ilated upper lobe vessels, </i><i><b>E</b></i><i>ffusion [pleural]), </i><mark class=\"hl mech\"><i><b>ABG</b></i></mark><i> , </i><i><b>BNP or NT-proBNP</b></i><i> (high sensitivity to differentiate cardiac vs. COPD/asthma dyspnea!), </i><mark class=\"hl mech\"><i><b>Troponin</b></i></mark><i> , </i><mark class=\"hl mech\"><i><b>RFTs + Electrolytes</b></i></mark><i> , </i><mark class=\"hl mech\"><i><b>CBC</b></i></mark><i> , Bedside </i><i><b>Lung Ultrasound </b></i><i>(</i><i><b>B-lines</b></i><i>) &amp; </i><mark class=\"hl mech\"><i><b>Echocardiogram</b></i></mark><i> .</i></li>\n</ul><h3><b>5. Treatment of Acute Pulmonary Edema (\"LMNOP\" — Updated!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i><b>Position &amp; Oxygen / NIV:</b></i><i> Sit upright (legs dangling); give Oxygen if </i><mark class=\"hl mech\"><i><b>SpO2 &lt; 90%</b></i></mark><i> ; start </i><i><b>NIV</b></i><i> (</i><i><b>CPAP</b></i><i> or </i><i><b>BiPAP</b></i><i>) early — markedly reduces need for intubation and mortality!</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i><b>IV Loop Diuretic (First-Line):</b></i><i> </i><mark class=\"hl rx\"><i><b>IV Furosemide</b></i></mark><i> 40–80 mg bolus (or 1–2.5× patient’s daily home oral dose if already on Lasix).</i></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl lab\"><i><b>IV Vasodilator (If SBP &gt; 110 mmHg — especially hypertensive pulmonary edema!):</b></i></mark><i> </i><mark class=\"hl rx\"><i><b>IV Nitroglycerin</b></i></mark><i> infusion (reduces preload &amp; afterload rapidly!).</i></span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><i>Note on Morphine: Historically used (\"LMNOP\"), now </i><i><b>NOT routinely recommended</b></i><i> (increases respiratory depression and mortality).</i></span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><mark class=\"hl lab\"><i><b>If Hypotensive / Cardiogenic Shock (SBP &lt; 90 mmHg):</b></i></mark><i> Avoid vasodilators; use </i><i><b>Inotropes/Vasopressors</b></i><i> (</i><mark class=\"hl rx\"><i><b> Norepinephrine</b></i></mark><i> +/- </i><mark class=\"hl rx\"><i><b>Dobutamine</b></i></mark><i> or </i><i><b>Milrinone</b></i><i>).</i></span></p>\n<p class=\"num\"><span class=\"n\">6.</span><span class=\"nt\"><i><b>Identify &amp; Treat Trigger:</b></i><i> Urgent PCI if STEMI, rate control if rapid AFib, antibiotics if pneumonia.</i></span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u56\">← Case 6</button><button class=\"nv\" data-u=\"u58\">Case 8 →</button></nav></article><article class=\"view unit\" id=\"u58\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 8</span><h1>Chronic Heart Failure with Reduced Ejection Fraction (HFrEF)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Chronic+Heart+Failure+with+Reduced+Ejection+Fraction+%28HFrEF%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p><i>Clinical syndrome of impaired ventricular filling or ejection with </i><i><b>LVEF ≤ 40%</b></i><i> (Heart Failure with Mildly Reduced EF = </i><i><b>HFmrEF</b></i><i>, LVEF 41–49%).</i></p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i><b>Ischemic Heart Disease (#1 Overall Cause):</b></i><i> Prior MI, chronic CAD.</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i><b>Pressure / Volume Overload:</b></i><i> Long-standing uncontrolled </i><i><b>Hypertension</b></i><i>, </i><i><b>Valvular Heart Disease</b></i><i> (AS, AR, MR).</i></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><i><b>Non-Ischemic Cardiomyopathies:</b></i><i> Dilated cardiomyopathy (idiopathic/familial), Peripartum, Alcoholic, Chemotherapy (</i><i><b>Doxorubicin</b></i><i>, Trastuzumab), Viral myocarditis, Tachycardia-induced (uncontrolled AFib).</i></span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><i><b>High-Output HF:</b></i><i> Severe Anemia, Thyrotoxicosis, Beriberi (Thiamine deficiency), AV fistula.</i></span></p><h3><b>3. Clinical Picture &amp; Staging (NYHA Functional Class I–IV)</b></h3><ul>\n<li class=\"l1\"><i><b>Left-Sided Symptoms:</b></i><i> Exertional dyspnea, orthopnea, PND, fatigue, dry nocturnal cough.</i></li>\n<li class=\"l1\"><i><b>Right-Sided Symptoms:</b></i><i> Ankle/leg edema, abdominal bloating/RUQ pain (hepatic congestion), anorexia.</i></li>\n<li class=\"l1\"><i><b>NYHA Class:</b></i><i> I (No limitation); II (Symptoms on ordinary exertion); III (Symptoms on minimal exertion); IV (Symptoms at rest).</i></li>\n</ul><h3><b>4. Investigations</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><i><b>Transthoracic Echocardiogram (TTE):</b></i></mark><i> </i><mark class=\"hl mech\"><i><b>Gold standard</b></i></mark><i> to measure </i><i><b>LVEF</b></i><i>, chamber sizes, valve function, and </i><i><b>PASP</b></i><i> (Pulmonary Artery Systolic Pressure).</i></li>\n<li class=\"l1\"><i><b>BNP / NT-proBNP</b></i><i>, </i><mark class=\"hl mech\"><i><b>ECG</b></i></mark><i> , </i><mark class=\"hl mech\"><i><b>CXR</b></i></mark><i> , </i><mark class=\"hl mech\"><i><b>CBC</b></i></mark><i> , </i><i><b>Iron Studies (Ferritin &amp; TSAT)</b></i><i>, </i><mark class=\"hl mech\"><i><b>RFTs/Electrolytes</b></i></mark><i> , </i><mark class=\"hl mech\"><i><b>LFTs</b></i></mark><i> , </i><mark class=\"hl mech\"><i><b>TSH</b></i></mark><i> , </i><mark class=\"hl mech\"><i><b>HbA1c</b></i></mark><i> , Lipid Profile, Coronary Angiography (to rule out ischemic etiology).</i></li>\n</ul><h3><b>5. Treatment — THE 4 PILLARS OF HFrEF GDMT (PROVEN TO REDUCE MORTALITY!)</b></h3><p class=\"muted\"><i>(Start all 4 pillars early at low doses and uptitrate every 2–4 weeks as BP, HR, K+, and Creatinine allow!)</i></p><table class=\"t \"><tr class=\"hd\"><th><p class=\"muted\"><i><b>Pillar</b></i></p></th><th><p class=\"muted\"><i><b>Drug Class &amp; Examples</b></i></p></th><th><p class=\"muted\"><i><b>Key Clinical Pearls</b></i></p></th></tr><tr><td><p class=\"muted\"><i><b>Pillar 1</b></i></p></td><td><p><i><b>ARNI</b></i><i> (</i><mark class=\"hl rx\"><i><b> Sacubitril/Valsartan</b></i></mark><i> ) preferred — OR </i><i><b>ACE-i </b></i><i>(Ramipril/Enalapril) / </i><mark class=\"hl rx\"><i><b>ARB</b></i></mark></p></td><td><p><i>Must have </i><i><b>36-hour washout</b></i><i> when switching from ACE-i to Sacubitril/Valsartan to prevent </i><i><b>angioedema</b></i><i>!</i></p></td></tr><tr><td><p class=\"muted\"><i><b>Pillar 2</b></i></p></td><td><p><i><b>Evidence-Based Beta-Blocker</b></i><i> (</i><mark class=\"hl rx\"><i><b> Bisoprolol, Carvedilol, or Metoprolol Succinate</b></i></mark><i> ONLY!)</i></p></td><td><p><i>Start ONLY when </i><i><b>euvolemic</b></i><i> (not in acute pulmonary edema!).</i></p></td></tr><tr><td><p class=\"muted\"><i><b>Pillar 3</b></i></p></td><td><p><i><b>MRA</b></i><i> (Mineralocorticoid Receptor Antagonist: </i><mark class=\"hl rx\"><i><b>Spironolactone</b></i></mark><i> or </i><i><b>Eplerenone</b></i><i>)</i></p></td><td><p><i>Monitor </i><i><b>K+</b></i><i> &amp; Creatinine (avoid if K+ &gt; 5.0 or eGFR &lt; 30); Eplerenone avoids gynecomastia.</i></p></td></tr><tr><td><p class=\"muted\"><i><b>Pillar 4</b></i></p></td><td><p><i><b>SGLT2 Inhibitor</b></i><i> (</i><i><b>Dapagliflozin 10 mg</b></i><i> or </i><i><b>Empagliflozin 10 mg </b></i><i>OD)</i></p></td><td><p><i>Works </i><i><b>regardless of Diabetes status</b></i><i>! Minimal BP effect, protects kidneys!</i></p></td></tr></table><ul>\n<li class=\"l1\"><i><b>Symptomatic Congestion Relief (Does NOT reduce mortality, used PRN for fluid overload):</b></i><i> </i><i><b>Loop Diuretics</b></i><i> (</i><mark class=\"hl rx\"><i><b> Furosemide</b></i></mark><i> , </i><i><b>Torsemide</b></i><i>, or Bumetanide) + Sodium/fluid restriction (if severe).</i></li>\n<li class=\"l1\"><i><b>Add-On / Device Therapy:</b></i></li>\n<li class=\"l2\"><i><b>Ivabradine</b></i><i> (if sinus rhythm, LVEF ≤ 35%, and resting HR ≥ 70 bpm despite max Beta-blocker).</i></li>\n<li class=\"l2\"><i><b>IV Iron (Ferric Carboxymaltose):</b></i><i> If iron-deficient (Ferritin &lt; 100, or 100–299 with TSAT &lt; 20%) -&gt; improves symptoms &amp; reduces hospitalizations!</i></li>\n<li class=\"l2\"><i><b>ICD</b></i><i> (Implantable Cardioverter-Defibrillator): If LVEF ≤ 35% despite ≥ 3 months of GDMT (primary prevention of </i><i><b>SCD</b></i><i>).</i></li>\n<li class=\"l2\"><i><b>CRT</b></i><i> (Cardiac Resynchronization Therapy / Biventricular Pacemaker): If LVEF ≤ 35% + sinus rhythm + </i><i><b>LBBB with QRS ≥ 150 ms</b></i><i>.</i></li>\n<li class=\"l2\"><i><b>AVOID:</b></i><i> </i><mark class=\"hl rx\"><i><b>NSAIDs</b></i></mark><i> , non-dihydropyridine </i><i><b>CCBs</b></i><i> (Verapamil/Diltiazem), and </i><i><b>Thiazolidinediones</b></i><i> (Pioglitazone)!</i></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u57\">← Case 7</button><button class=\"nv\" data-u=\"u59\">Case 9 →</button></nav></article><article class=\"view unit\" id=\"u59\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 9</span><h1>Heart Failure with Preserved Ejection Fraction (HFpEF)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Heart+Failure+with+Preserved+Ejection+Fraction+%28HFpEF%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p><i>Clinical syndrome of Heart Failure (symptoms/signs + elevated BNP + structural/diastolic dysfunction) with </i><i><b>LVEF ≥ 50%</b></i><i> (\"Diastolic Heart Failure\" — stiff left ventricle fails to relax and fill properly).</i></p><h3><b>2. Etiology &amp; Classic Patient Profile (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i><b>Long-Standing Hypertension</b></i><i> (#1 cause — concentric LVH).</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i><b>Metabolic / Elderly Profile:</b></i><i> Elderly female, Obesity, </i><mark class=\"hl lab\"><i><b>T2DM</b></i></mark><i> , </i><mark class=\"hl lab\"><i><b>AFib</b></i></mark><i> , </i><mark class=\"hl lab\"><i><b>CKD</b></i></mark><i> , </i><mark class=\"hl lab\"><i><b>CAD</b></i></mark><i> .</i></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><i><b>Infiltrative Cardiomyopathies:</b></i><i> </i><i><b>Cardiac Amyloidosis</b></i><i>, Hemochromatosis, </i><mark class=\"hl lab\"><i><b>HCM</b></i></mark><i> , Constrictive Pericarditis.</i></span></p><h3><b>3. Investigations</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><i><b>Echocardiogram:</b></i></mark><i> </i><i><b>LVEF ≥ 50%</b></i><i>, Concentric </i><i><b>LVH</b></i><i>, Left Atrial enlargement, </i><i><b>Diastolic Dysfunction</b></i><i> (elevated </i><i><b>E/e’ ratio</b></i><i> &gt; 14).</i></li>\n<li class=\"l1\"><i><b>BNP / NT-proBNP</b></i><i> (may be lower in obese patients!), </i><i><b>H2FPEF Score</b></i><i>.</i></li>\n</ul><h3><b>4. Treatment</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i><b>SGLT2 Inhibitors (Empagliflozin or Dapagliflozin):</b></i><i> </i><i><b>Class I First-Line Disease-Modifying Therapy</b></i><i> in HFpEF (reduces HF hospitalizations &amp; CV death!).</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i><b>Diuretics</b></i><i> (Furosemide/Torsemide) for volume overload/edema.</i></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><i><b>Finerenone</b></i><i> (non-steroidal MRA — recently shown to reduce events in HFpEF/HFmrEF) or </i><mark class=\"hl rx\"><i><b>Spironolactone</b></i></mark><i> ; </i><mark class=\"hl rx\"><i><b>GLP-1 RA</b></i></mark><i> (Semaglutide/Tirzepatide) if obese.</i></span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><i>Aggressively control </i><i><b>BP</b></i><i>, </i><mark class=\"hl lab\"><i><b>AFib</b></i></mark><i> rate/rhythm, ischemia, and obesity.</i></span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u58\">← Case 8</button><button class=\"nv\" data-u=\"u60\">Case 10 →</button></nav></article><article class=\"view unit\" id=\"u60\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 10</span><h1>Mitral Stenosis (MS) — an Egyptian Cardiology Staple</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Mitral+Stenosis+%28MS%29+%E2%80%94+an+Egyptian+Cardiology+Staple\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p><i>Narrowing of the mitral valve orifice (normal 4–6 cm²; severe </i><i><b>&lt; 1.5 cm²</b></i><i>), obstructing blood flow from the Left Atrium (</i><i><b>LA</b></i><i>) to the Left Ventricle (</i><i><b>LV</b></i><i>) during diastole.</i></p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i><b>Rheumatic Heart Disease (RHD) — &gt; 95% of cases!</b></i><i> (Extremely common in Egypt; typically young-to-middle-aged </i><i><b>females</b></i><i> presenting 10–20 years after childhood </i><i><b>Acute Rheumatic Fever</b></i><i>).</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i><b>Degenerative Mitral Annular Calcification</b></i><i> (rarely causes severe MS in elderly) or Congenital parachute mitral valve.</i></span></p><h3><b>3. Pathophysiology &amp; Clinical Picture</b></h3><p><i>Obstruction -&gt; elevated LA pressure -&gt; LA dilation -&gt; </i><mark class=\"hl lab\"><i><b>Atrial Fibrillation</b></i></mark><i> + Pulmonary venous hypertension -&gt; Pulmonary arterial hypertension -&gt; Right Ventricular failure.</i></p>\n<ul>\n<li class=\"l1\"><i><b>Symptoms:</b></i><i> Exertional dyspnea, orthopnea, PND, </i><i><b>hemoptysis</b></i><i> (rupture of bronchial veins), </i><mark class=\"hl lab\"><i><b>palpitations (AFib)</b></i></mark><i> , </i><i><b>systemic thromboembolism / stroke</b></i><i>, </i><i><b>Ortner’s Syndrome</b></i><i> (hoarseness from enlarged LA compressing left recurrent laryngeal nerve), dysphagia.</i></li>\n<li class=\"l1\"><i><b>Classic Exam Signs:</b></i></li>\n<li class=\"l2\"><i><b>Malar Flush</b></i><i> (pinkish-purple patches on cheeks).</i></li>\n<li class=\"l2\"><i><b>Loud S1</b></i><i> (until valve calcifies), </i><i><b>Opening Snap (OS)</b></i><i> after S2, followed by a </i><i><b>Low-Pitched Mid-Diastolic Rumbling Murmur</b></i><i> best heard with the </i><i><b>BELL</b></i><i> at the apex in the </i><i><b>left lateral decubitus position</b></i><i> (with presystolic accentuation if in sinus rhythm!).</i></li>\n</ul><h3><b>4. Investigations</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><i><b>ECG:</b></i></mark><i> </i><i><b>P-Mitrale</b></i><i> (broad notched P wave &gt; 120 ms in Lead II) or </i><i><b>Atrial Fibrillation</b></i><i> + Right Axis Deviation / RVH.</i></li>\n<li class=\"l1\"><mark class=\"hl mech\"><i><b>CXR:</b></i></mark><i> Straightening of left heart border, </i><i><b>double right heart border</b></i><i>, elevation of left main bronchus, pulmonary congestion.</i></li>\n<li class=\"l1\"><mark class=\"hl mech\"><i><b>Echocardiogram (Gold Standard):</b></i></mark><i> Valve area (</i><i><b>MVA &lt; 1.5 cm²</b></i><i> = severe), transmitral pressure gradient, </i><i><b>Wilkins Score</b></i><i> (assesses leaflet mobility/calcification for balloon valvuloplasty!), </i><i><b>LA thrombus</b></i><i> (check via </i><i><b>TEE</b></i><i> [Transesophageal Echo] before intervention!).</i></li>\n</ul><h3><b>5. Treatment</b></h3><ul>\n<li class=\"l1\"><i><b>Medical:</b></i></li>\n<li class=\"l2\"><i><b>Diuretics</b></i><i> for pulmonary congestion.</i></li>\n<li class=\"l2\"><i><b>Heart Rate Control</b></i><i> (</i><i><b>Beta-blockers</b></i><i> or Digoxin — slowing HR lengthens diastole, allowing better LA emptying!).</i></li>\n<li class=\"l2\"><mark class=\"hl rx\"><i><b>Anticoagulation (CRITICAL!):</b></i></mark><i> If </i><mark class=\"hl lab\"><i><b>AFib</b></i></mark><i> , prior embolism, or LA thrombus -&gt; </i><mark class=\"hl lab\"><i><b>WARFARIN ONLY</b></i></mark><i> (Target </i><mark class=\"hl mech\"><i><b>INR 2.0–3.0</b></i></mark><i> )! </i><mark class=\"hl rx\"><i><b>DOACs (Rivaroxaban/Apixaban) are CONTRAINDICATED in moderate-to-severe Rheumatic Mitral Stenosis!</b></i></mark></li>\n<li class=\"l2\"><i><b>Secondary Rheumatic Prophylaxis:</b></i><i> </i><i><b>IM Benzathine Penicillin G</b></i><i> 1.2 million units every 3–4 weeks.</i></li>\n<li class=\"l1\"><i><b>Mechanical Intervention (For Symptomatic Severe MS &lt; 1.5 cm²):</b></i></li>\n<li class=\"l2\"><i><b>PMBV</b></i><i> (Percutaneous Mitral Balloon Valvuloplasty) — treatment of choice if favorable anatomy (</i><i><b>Wilkins score ≤ 8</b></i><i>), </i><i><b>no LA thrombus</b></i><i>, and </i><i><b>&lt; moderate MR</b></i><i>!</i></li>\n<li class=\"l2\"><i><b>Mitral Valve Replacement (MVR):</b></i><i> If heavily calcified valve, LA thrombus, or significant MR.</i></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u59\">← Case 9</button><button class=\"nv\" data-u=\"u61\">Case 11 →</button></nav></article><article class=\"view unit\" id=\"u61\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 11</span><h1>Mitral Regurgitation (MR)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Mitral+Regurgitation+%28MR%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p class=\"muted\"><i>Abnormal systolic backflow of blood from the Left Ventricle into the Left Atrium due to mitral apparatus dysfunction.</i></p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i><b>Primary (Organic) MR — Leaflet/Apparatus Problem:</b></i></span></p>\n<ul>\n<li class=\"l2\"><i><b>Mitral Valve Prolapse (MVP / Myxomatous degeneration)</b></i><i> — #1 in developed world (young females, mid-systolic click).</i></li>\n<li class=\"l2\"><i><b>Rheumatic Heart Disease</b></i><i> (common in Egypt!).</i></li>\n<li class=\"l2\"><i><b>Infective Endocarditis</b></i><i> (leaflet perforation/chordal rupture).</i></li>\n<li class=\"l2\"><i><b>Acute Papillary Muscle Rupture</b></i><i> (post-Inferior STEMI — surgical emergency!).</i></li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i><b>Secondary (Functional) MR — LV Dilation Pulls Normal Leaflets Apart:</b></i></span></p>\n<ul>\n<li class=\"l2\"><i><b>Dilated Cardiomyopathy / HFrEF</b></i><i> or </i><i><b>Ischemic LV remodeling</b></i><i>.</i></li>\n</ul><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><i><b>Acute MR</b></i><i> (e.g., post-MI/endocarditis): Sudden </i><i><b>cardiogenic shock &amp; flash pulmonary edema</b></i><i>!</i></li>\n<li class=\"l1\"><i><b>Chronic MR:</b></i><i> Slowly progressive exertional dyspnea, fatigue, palpitations (</i><mark class=\"hl lab\"><i><b> AFib</b></i></mark><i> ).</i></li>\n<li class=\"l1\"><i><b>Exam:</b></i><i> Displaced hyperdynamic apical impulse, </i><i><b>Soft S1</b></i><i>, </i><i><b>Holosystolic (Pansystolic) Blowing Murmur</b></i><i> best heard at </i><i><b>Apex</b></i><i> radiating to </i><i><b>Left Axilla</b></i><i>, +/- S3 gallop.</i></li>\n</ul><h3><b>4. Investigations &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><i><b>Echocardiogram:</b></i></mark><i> Evaluates MR severity, </i><i><b>LVEF</b></i><i>, </i><i><b>LVESD</b></i><i> (LV End-Systolic Diameter), and mechanism (primary vs. secondary).</i></li>\n<li class=\"l1\"><i><b>Treatment:</b></i></li>\n<li class=\"l2\"><i>Acute Severe MR: </i><i><b>IV Vasodilators</b></i><i> (Nitroprusside) + Diuretics + </i><i><b>IABP</b></i><i> (Intra-Aortic Balloon Pump) bridge to </i><i><b>Emergent Surgery</b></i><i>.</i></li>\n<li class=\"l2\"><i>Chronic Primary MR: Vasodilators do NOT delay surgery; </i><i><b>Surgical Mitral Valve Repair (preferred over Replacement)</b></i><i> when </i><i><b>symptomatic</b></i><i> OR asymptomatic with </i><i><b>LVEF ≤ 60%</b></i><i> or </i><i><b>LVESD ≥ 40 mm</b></i><i>!</i></li>\n<li class=\"l2\"><i>Chronic Secondary MR: Optimize </i><i><b>GDMT</b></i><i> (4 pillars of HFrEF!) +/- </i><i><b>CRT</b></i><i>; consider </i><i><b>TEER</b></i><i> (Transcatheter Edge-to-Edge Repair / </i><i><b>MitraClip</b></i><i>) if severe symptoms persist despite optimal GDMT.</i></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u60\">← Case 10</button><button class=\"nv\" data-u=\"u62\">Case 12 →</button></nav></article><article class=\"view unit\" id=\"u62\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 12</span><h1>Aortic Stenosis (AS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Aortic+Stenosis+%28AS%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p><i>Narrowing of the aortic valve orifice (normal 3–4 cm²; severe </i><i><b>&lt; 1.0 cm²</b></i><i> or mean gradient </i><i><b>≥ 40 mmHg</b></i><i>), obstructing LV outflow.</i></p><h3><b>2. Etiology (Separated by Age!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i><b>Elderly (&gt; 65–70 Years):</b></i><i> </i><i><b>Senile Calcific Degeneration</b></i><i> (#1 overall).</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i><b>Middle-Aged (40–65 Years):</b></i><i> </i><i><b>Congenital Bicuspid Aortic Valve</b></i><i> (accelerated calcification + associated with Aortic Coarctation &amp; ascending aortic aneurysm!).</i></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><i><b>Rheumatic Heart Disease:</b></i><i> Commissural fusion (usually accompanies Mitral valve disease in Egypt).</i></span></p><h3><b>3. Clinical Picture (Classic Triad of Prognosis — \"SAD\")</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i><b>A</b></i><i>ngina (~5 years median survival if untreated).</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i><b>S</b></i><i>yncope (exertional — ~3 years survival).</i></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><i><b>D</b></i><i>yspnea / Heart Failure (~1.5–2 years survival!).</i></span></p>\n<ul>\n<li class=\"l1\"><i><b>Exam:</b></i><i> Slow-rising, weak pulse (</i><i><b>Pulsus Parvus et Tardus</b></i><i>), </i><i><b>S4</b></i><i>, </i><i><b>Harsh Crescendo-Decrescendo (Diamond-Shaped) Systolic Ejection Murmur</b></i><i> best heard at </i><i><b>Right 2nd Intercostal Space</b></i><i> radiating to </i><i><b>Carotids</b></i><i>, soft/absent </i><i><b>A2</b></i><i> (or paradoxical S2 splitting).</i></li>\n<li class=\"l1\"><i>Associated Syndrome: </i><i><b>Heyde’s Syndrome</b></i><i> = Severe AS + GI Bleeding from </i><i><b>Angiodysplasia</b></i><i> (due to shear-stress cleavage of </i><i><b>von Willebrand Factor</b></i><i>!).</i></li>\n</ul><h3><b>4. Investigations &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><i><b>Echocardiogram (Gold Standard):</b></i></mark><i> Valve area (</i><i><b>AVA &lt; 1.0 cm²</b></i><i>), Jet velocity (</i><i><b>≥ 4.0 m/s</b></i><i>), Mean gradient (</i><i><b>≥ 40 mmHg</b></i><i>). NEVER perform an exercise stress test in SYMPTOMATIC severe AS!</i></li>\n<li class=\"l1\"><i><b>Medical Management Caution:</b></i><i> </i><mark class=\"hl rx\"><i><b>AVOID aggressive vasodilators (Nitrates/ACE-i)</b></i></mark><i> and </i><i><b>aggressive diuretics</b></i><i> (preload-dependent fixed afterload -&gt; severe hypotension/syncope!).</i></li>\n<li class=\"l1\"><i><b>Definitive Treatment (ONLY cure for Severe Symptomatic AS or Severe AS with LVEF &lt; 50%):</b></i></li>\n<li class=\"l2\"><i><b>TAVI / TAVR</b></i><i> (Transcatheter Aortic Valve Implantation/Replacement — preferred in elderly &gt; 75 yrs or high/intermediate surgical risk).</i></li>\n<li class=\"l2\"><i><b>SAVR</b></i><i> (Surgical Aortic Valve Replacement — preferred in younger patients &lt; 65–70 yrs or bicuspid valve).</i></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u61\">← Case 11</button><button class=\"nv\" data-u=\"u63\">Case 13 →</button></nav></article><article class=\"view unit\" id=\"u63\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 13</span><h1>Aortic Regurgitation (AR)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Aortic+Regurgitation+%28AR%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p class=\"muted\"><i>Diastolic reflux of blood from the aorta back into the Left Ventricle due to incompetent aortic valve leaflets or aortic root dilation.</i></p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i><b>Valve Leaflet Disease:</b></i><i> </i><i><b>Rheumatic Heart Disease</b></i><i> (Egypt), </i><i><b>Infective Endocarditis</b></i><i> (acute AR!), Bicuspid aortic valve.</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i><b>Aortic Root Dilation:</b></i><i> </i><i><b>Hypertension</b></i><i>, </i><mark class=\"hl lab\"><i><b>Acute Aortic Dissection</b></i></mark><i> (acute AR!), </i><i><b>Marfan Syndrome</b></i><i>, </i><i><b>Ankylosing Spondylitis</b></i><i>, Tertiary Syphilis.</i></span></p><h3><b>3. Clinical Picture &amp; Classic Peripheral Signs (Due to Wide Pulse Pressure!)</b></h3><ul>\n<li class=\"l1\"><i>Dyspnea, pounding heartbeat when lying on left side, angina (reduced diastolic coronary perfusion).</i></li>\n<li class=\"l1\"><i><b>Exam:</b></i></li>\n<li class=\"l2\"><i><b>Wide Pulse Pressure</b></i><i> (e.g., 160/50 mmHg) + </i><i><b>Water-Hammer (Corrigan’s) Pulse</b></i><i> (bounding, rapidly collapsing).</i></li>\n<li class=\"l2\"><i><b>de Musset’s sign</b></i><i> (head bobbing), </i><i><b>Quincke’s sign</b></i><i> (capillary nailbed pulsation), </i><i><b>Traube’s pistol-shot femorals</b></i><i>.</i></li>\n<li class=\"l2\"><i><b>High-Pitched Blowing Early Diastolic Decrescendo Murmur</b></i><i> best heard at </i><i><b>Left Sternal Border (3rd–4th ICS)</b></i><i> with patient </i><i><b>sitting upright, leaning forward, at end-expiration</b></i><i>! (Plus </i><i><b>Austin Flint murmur</b></i><i> at apex mimicking MS).</i></li>\n</ul><h3><b>4. Treatment</b></h3><ul>\n<li class=\"l1\"><i><b>Acute Severe AR</b></i><i> (Endocarditis / Aortic Dissection): </i><i><b>Emergent Surgical AVR!</b></i><i> (</i><i><b>IABP is STRICTLY CONTRAINDICATED</b></i><i> in AR because balloon inflation during diastole worsens regurgitation!).</i></li>\n<li class=\"l1\"><i><b>Chronic Severe AR:</b></i><i> Vasodilators (</i><i><b>Nifedipine</b></i><i> or </i><mark class=\"hl rx\"><i><b>ACE-i/ARB</b></i></mark><i> ) for HTN/symptom control; </i><i><b>Surgical AVR</b></i><i> when </i><i><b>symptomatic</b></i><i> OR asymptomatic with </i><i><b>LVEF &lt; 50–55% </b></i><i>or </i><i><b>LVESD &gt; 50 mm</b></i><i>.</i></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u62\">← Case 12</button><button class=\"nv\" data-u=\"u64\">Case 14 →</button></nav></article><article class=\"view unit\" id=\"u64\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 14</span><h1>Acute Pericarditis, Pericardial Effusion &amp; Cardiac Tamponade</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Pericarditis%2C+Pericardial+Effusion+%26+Cardiac+Tamponade\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><ul>\n<li class=\"l1\"><i><b>Acute Pericarditis:</b></i><i> Inflammation of the pericardial sac.</i></li>\n<li class=\"l1\"><mark class=\"hl lab\"><i><b>Cardiac Tamponade:</b></i></mark><i> Life-threatening compression of the heart chambers by rapid or large fluid accumulation in the pericardial space, impairing ventricular filling and cardiac output.</i></li>\n</ul><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i><b>Idiopathic / Viral (~80–90%):</b></i><i> Coxsackievirus, Echovirus, Adenovirus, COVID-19.</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i><b>Bacterial / Tuberculous:</b></i><i> </i><i><b>TB Pericarditis</b></i><i> (very important in Egypt — leads to </i><i><b>Constrictive Pericarditis</b></i><i>!), purulent bacterial.</i></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><i><b>Post-MI:</b></i><i> Early (fibrinous) vs. Late (</i><i><b>Dressler’s Syndrome</b></i><i>).</i></span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><i><b>Systemic / Metabolic / Malignancy:</b></i><i> </i><i><b>Uremia</b></i><i> (CKD/dialysis), </i><mark class=\"hl lab\"><i><b>SLE</b></i></mark><i> / </i><mark class=\"hl lab\"><i><b>RA</b></i></mark><i> , </i><i><b>Malignancy</b></i><i> (lung/breast/lymphoma — common cause of large hemorrhagic effusion/tamponade!), Aortic dissection, Chest trauma.</i></span></p><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><i><b>Acute Pericarditis (Diagnosis requires ≥ 2 of 4 Criteria):</b></i></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i><b>Sharp pleuritic chest pain</b></i><i> worse lying flat/inspiration, </i><i><b>RELIEVED by sitting up and leaning forward</b></i><i>!</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i><b>Pericardial Friction Rub</b></i><i> (scratchy high-pitched sound best heard at left lower sternal border leaning forward).</i></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl mech\"><i><b>ECG Changes:</b></i></mark><i> </i><i><b>Diffuse concave-upward ST elevation</b></i><i> across almost ALL leads (except aVR/V1) + </i><i><b>PR-segment depression</b></i><i>!</i></span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><i>New/worsening </i><i><b>Pericardial Effusion</b></i><i> on Echo.</i></span></p>\n<ul>\n<li class=\"l1\"><i><b>Cardiac Tamponade (Beck’s Triad):</b></i></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i><b>Hypotension.</b></i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i><b>JVD</b></i><i> (elevated jugular venous pressure with </i><i><b>absent Y-descent</b></i><i>).</i></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><i><b>Muffled (distant) heart sounds.</b></i></span></p>\n<ul>\n<li class=\"l2\"><i>Plus: </i><i><b>Pulsus Paradoxus</b></i><i> (drop in SBP </i><i><b>&gt; 10 mmHg during inspiration</b></i><i>) and </i><i><b>Electrical Alternans</b></i><i> on ECG (alternating QRS amplitude as heart swings in fluid)!</i></li>\n</ul><h3><b>4. Investigations</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><i><b>ECG</b></i></mark><i> (diffuse concave ST elevation + PR depression vs. focal convex STEMI!), </i><mark class=\"hl mech\"><i><b>CXR</b></i></mark><i> (\"water-bottle\" heart if large effusion), </i><mark class=\"hl mech\"><i><b>CRP/ESR</b></i></mark><i> , </i><mark class=\"hl mech\"><i><b>Troponin</b></i></mark><i> (elevated if concurrent Myopericarditis), </i><mark class=\"hl mech\"><i><b>Echocardiogram</b></i></mark><i> (confirms effusion; </i><i><b>RV diastolic collapse &amp; RA systolic collapse</b></i><i> = tamponade!).</i></li>\n</ul><h3><b>5. Treatment</b></h3><ul>\n<li class=\"l1\"><i><b>Acute Idiopathic/Viral Pericarditis:</b></i></li>\n<li class=\"l2\"><mark class=\"hl rx\"><i><b>High-dose NSAIDs</b></i></mark><i> (Ibuprofen 600–800 mg TID or Aspirin 750–1,000 mg TID) for 1–2 weeks + </i><mark class=\"hl rx\"><i><b>Colchicine 0.5 mg OD/BID for 3 MONTHS</b></i></mark><i> (halves recurrence rate!).</i></li>\n<li class=\"l2\"><i>AVOID Corticosteroids as first-line (increases recurrence!) — reserve only for autoimmune, uremic (dialysis!), or refractory cases.</i></li>\n<li class=\"l1\"><i><b>Cardiac Tamponade:</b></i></li>\n<li class=\"l2\"><mark class=\"hl rx\"><i><b>Emergent Pericardiocentesis</b></i></mark><i> (ultrasound-guided)!</i></li>\n<li class=\"l2\"><i>Support preload temporarily with </i><mark class=\"hl rx\"><i><b>IV Normal Saline boluses</b></i></mark><i> while preparing drainage — </i><i><b>AVOID diuretics and vasodilators!</b></i></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u63\">← Case 13</button><button class=\"nv\" data-u=\"u65\">Case 15 →</button></nav></article><article class=\"view unit\" id=\"u65\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 15</span><h1>Infective Endocarditis (IE)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Infective+Endocarditis+%28IE%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p><i>Microbial infection of the endocardial surface of the heart, typically affecting native or prosthetic heart valves (</i><i><b>vegetation</b></i><i> = platelets + fibrin + microbes).</i></p><h3><b>2. Etiology &amp; Predisposing Factors (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i><b>Pathogens by Clinical Scenario:</b></i></span></p>\n<ul>\n<li class=\"l2\"><i><b>Subacute IE (Native damaged valves, e.g., RHD/MVP after dental work):</b></i><i> </i><i><b>Viridans Streptococci</b></i><i> (#1 in community/dental procedures).</i></li>\n<li class=\"l2\"><i><b>Acute IE (Healthy or damaged valves, IV Drug Users [IVDU]):</b></i><i> </i><i><b>Staphylococcus aureus</b></i><i> (#1 in IVDU — affects </i><i><b>Tricuspid valve</b></i><i>!; also rapid severe destruction!).</i></li>\n<li class=\"l2\"><i><b>Prosthetic Valve IE:</b></i><i> Staphylococcus epidermidis (early &lt; 2–12 mos), S. aureus, Enterococcus.</i></li>\n<li class=\"l2\"><i><b>GI / GU Procedures or Colon Cancer:</b></i><i> Enterococcus, </i><i><b>Streptococcus gallolyticus (bovis)</b></i><i> -&gt; </i><i><b>MUST do Colonoscopy</b></i><i> to rule out </i><i><b>Colorectal Cancer</b></i><i>!</i></li>\n<li class=\"l2\"><i><b>Culture-Negative IE:</b></i><i> Prior antibiotics, </i><i><b>HACEK</b></i><i> organisms, Coxiella burnetii, Bartonella, Brucella (important in Egypt!).</i></li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i><b>Predisposing Heart Conditions:</b></i><i> </i><i><b>Rheumatic Heart Disease</b></i><i> (huge in Egypt), Prosthetic valves, Bicuspid aortic valve, </i><mark class=\"hl lab\"><i><b>VSD</b></i></mark><i> , IV drug use, Indwelling venous catheters.</i></span></p><h3><b>3. Clinical Picture (\"FEVER + NEW MURMUR\")</b></h3><ul>\n<li class=\"l1\"><i>Fever (most common — &gt; 90%), chills, night sweats, weight loss, malaise, </i><i><b>new or changing regurgitant murmur</b></i><i>.</i></li>\n<li class=\"l1\"><i><b>Immunologic &amp; Vascular Phenomena (Mnemonic: \"FROM JANE\"):</b></i></li>\n<li class=\"l2\"><i><b>F</b></i><i>ever | </i><i><b>R</b></i><i>oth spots (retinal hemorrhages with pale centers) | </i><i><b>O</b></i><i>sler nodes (painful violet nodules on finger/toe pads) | </i><i><b>M</b></i><i>urmur | </i><i><b>J</b></i><i>aneway lesions (painless hemorrhagic macules on palms/soles) | </i><i><b>A</b></i><i>nemia | </i><i><b>N</b></i><i>ail-bed </i><i><b>splinter hemorrhages</b></i><i> | </i><i><b>E</b></i><i>mboli (stroke, splenic/renal infarcts, septic pulmonary emboli in Tricuspid IE!).</i></li>\n</ul><h3><b>4. Investigations (Modified Duke Criteria)</b></h3><ul>\n<li class=\"l1\"><i><b>Blood Cultures (MANDATORY BEFORE ANTIBIOTICS!):</b></i><i> Draw </i><i><b>3 separate sets</b></i><i> from </i><i><b>3 different venipuncture sites</b></i><i> spaced apart (e.g., 30–60 min apart if stable) — never draw through old lines!</i></li>\n<li class=\"l1\"><mark class=\"hl mech\"><i><b>Echocardiography:</b></i></mark><i> Start with </i><i><b>TTE</b></i><i> (Transthoracic), proceed to </i><i><b>TEE</b></i><i> (Transesophageal — much higher sensitivity for vegetations, abscesses, and prosthetic valves!).</i></li>\n<li class=\"l1\"><i><b>Labs:</b></i><i> </i><mark class=\"hl mech\"><i><b>CBC</b></i></mark><i> , </i><mark class=\"hl mech\"><i><b>ESR/CRP</b></i></mark><i> (markedly elevated), </i><mark class=\"hl mech\"><i><b>Urinalysis</b></i></mark><i> (microscopic hematuria/GN), </i><i><b>RF</b></i><i> (positive).</i></li>\n</ul><h3><b>5. Complications</b></h3><ul>\n<li class=\"l1\"><i><b>Acute Heart Failure</b></i><i> (due to acute valve destruction/AR/MR — </i><i><b>#1 cause of death!</b></i><i>), Systemic septic emboli (Stroke, Mycotic aneurysm), Perivalvular abscess (new </i><i><b>AV block</b></i><i> on ECG!), Glomerulonephritis.</i></li>\n</ul><h3><b>6. Treatment</b></h3><ul>\n<li class=\"l1\"><i><b>Prolonged Bactericidal IV Antibiotics (4–6 Weeks)</b></i><i> tailored to blood culture sensitivities:</i></li>\n<li class=\"l2\"><i>Empirical Native Valve (Acute/Severe): </i><mark class=\"hl rx\"><i><b>IV Vancomycin + Ceftriaxone</b></i></mark><i> (or Ampicillin-Sulbactam + Gentamicin).</i></li>\n<li class=\"l2\"><i>Empirical Prosthetic Valve: </i><mark class=\"hl rx\"><i><b>IV Vancomycin + Gentamicin + Rifampin</b></i></mark><i> .</i></li>\n<li class=\"l1\"><i><b>Indications for Early Cardiac Surgery (\"5 Indications\"):</b></i></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i>Acute </i><i><b>Heart Failure</b></i><i> / Cardiogenic shock from valve regurgitation.</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i>Uncontrolled infection (</i><i><b>perivalvular abscess</b></i><i>, new heart block, persistent bacteremia &gt; 5–7 days).</i></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><i><b>Fungal IE</b></i><i> or multidrug-resistant organisms.</i></span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><i>Large mobile vegetation </i><i><b>&gt; 10 mm</b></i><i> with recurrent emboli.</i></span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><i>Prosthetic valve dehiscence.</i></span></p>\n<ul>\n<li class=\"l1\"><mark class=\"hl rx\"><i><b>Antibiotic Prophylaxis (Amoxicillin 2 g PO 1 hr before dental procedures):</b></i></mark><i> Reserved ONLY for highest-risk patients (Prosthetic valves, prior IE, unrepaired cyanotic congenital heart disease, cardiac transplant valvulopathy).</i></li>\n</ul>\n<p class=\"muted\"><i>End of Part 4A.</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u64\">← Case 14</button><button class=\"nv\" data-u=\"u66\">Case 16 →</button></nav></article><article class=\"view unit\" id=\"u66\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 16</span><h1>Atrial Fibrillation (AFIB) &amp; Atrial Flutter</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Atrial+Fibrillation+%28AFIB%29+%26+Atrial+Flutter\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>AFib</b></mark> (Atrial Fibrillation): Supraventricular tachyarrhythmia characterized by chaotic, uncoordinated atrial electrical activation (&gt; 350–600 bpm) resulting in an <b>\"irregularly irregular\"</b> ventricular rhythm.</li>\n<li class=\"l1\"><b>Atrial Flutter:</b> Organized macro-reentrant atrial circuit (~300 bpm) producing classic <b>\"sawtooth\" F-waves</b> (best seen in II, III, aVF) and often a regular 2:1 ventricular response (~150 bpm).</li>\n</ul><h3><b>2. Etiology (Separated — Mnemonic: \"PIRATES\")</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Structural &amp; Cardiac Causes:</b> <b>H</b>ypertension (#1 overall cause!), <b>I</b>schemic heart disease (<mark class=\"hl lab\"><b> CAD</b></mark> ), <b>R</b>heumatic <b>M</b>itral <b>S</b>tenosis (huge in Egypt!), Heart Failure, Pericarditis, Post-cardiac surgery.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Pulmonary Causes:</b> <b>P</b>neumonia, <mark class=\"hl lab\"><b>PE</b></mark> (Pulmonary Embolism), <mark class=\"hl lab\"><b>COPD</b></mark> , <mark class=\"hl lab\"><b>OSA</b></mark> (Obstructive Sleep Apnea).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Endocrine / Metabolic / Electrolyte Causes:</b> <b>T</b>hyrotoxicosis (Hyperthyroidism — <mark class=\"hl lab\"><b>MUST check TSH in every new AFib!</b></mark> ), Hypokalemia, Hypomagnesemia, <b>E</b>thanol (\"Holiday Heart Syndrome\").</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Age / Idiopathic:</b> Advanced age (&gt; 65 yrs), <b>S</b>ick Sinus Syndrome.</span></p><h3><b>3. Clinical Picture &amp; Classification</b></h3><ul>\n<li class=\"l1\"><b>Classification:</b> Paroxysmal (terminates &lt; 7 days), Persistent (&gt; 7 days), Long-standing persistent (&gt; 12 mos), Permanent (accepted).</li>\n<li class=\"l1\"><b>Symptoms:</b> Palpitations, dyspnea, fatigue, dizziness, chest pain; often <b>asymptomatic</b> (presenting first as <b>cardioembolic ischemic stroke</b>!).</li>\n<li class=\"l1\"><b>Exam:</b> <b>Irregularly irregular pulse</b>, <b>pulse deficit</b> (apical HR &gt; radial HR), <b>absent \"a\" waves</b> in JVP, variable S1 intensity.</li>\n</ul><h3><b>4. Investigations</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>12-Lead ECG (Diagnostic):</b></mark> <b>Absent P waves</b>, irregularly irregular R-R intervals, wavy fibrillatory baseline (typically narrow QRS unless BBB/aberrancy).</li>\n<li class=\"l1\"><b>Mandatory Workup:</b> <mark class=\"hl mech\"><b>TSH + Free T4</b></mark> , <mark class=\"hl mech\"><b>RFTs + Electrolytes</b></mark> (K+, Mg++), <mark class=\"hl mech\"><b>CBC</b></mark> , <mark class=\"hl mech\"><b>Echocardiogram</b></mark> (assess LA size, LVEF, <b>valvular MS!</b>), <mark class=\"hl mech\"><b>Troponin</b></mark> if ischemic symptoms.</li>\n</ul><h3><b>5. Complications</b></h3><ul>\n<li class=\"l1\"><b>Systemic Thromboembolism / Stroke</b> (5-fold higher risk due to stasis in <b>Left Atrial Appendage</b>), <b>Tachycardia-Induced Cardiomyopathy</b> (HF), hemodynamic instability.</li>\n</ul><h3><b>6. Treatment (The \"ABC\" Pathway)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>UNSTABLE Patient (Hypotension, Acute Pulmonary Edema, Ongoing Ischemia, Altered Mental Status):</b></span></p>\n<ul>\n<li class=\"l2\"><mark class=\"hl rx\"><b>Immediate Synchronized Electrical Cardioversion</b></mark> (120–200 J biphasic)!</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl rx\"><b>A — Anticoagulation (Stroke Prevention via</b></mark></span></p><h4><b>CHA2DS2-VAScCHA2​DS2​-VASc</b></h4><h4><b>Score):</b></h4><ul>\n<li class=\"l1\"><b>Score:</b> <b>C</b>HF (1), <b>H</b>TN (1), <b>A</b>ge ≥ 75 (<b>2</b>), <b>D</b>iabetes (1), <b>S</b>troke/TIA (<b>2</b>), <b>V</b>ascular disease (1), <b>A</b>ge 65–74 (1), <b>S</b>ex category [Female] (1).</li>\n<li class=\"l1\"><i>Anticoagulate if:</i> Score <b>≥ 2 in men</b> or <b>≥ 3 in women</b> (consider if 1 in men / 2 in women).</li>\n<li class=\"l1\"><i>Drug Choice:</i></li>\n<li class=\"l2\"><mark class=\"hl lab\"><b>Non-Valvular AFib:</b></mark> <b>DOACs</b> (Direct Oral Anticoagulants — <mark class=\"hl rx\"><b>Apixaban, Rivaroxaban, Dabigatran, Edoxaban</b></mark> ) are <b>first-line</b> (fewer intracranial bleeds than Warfarin, no INR checks!).</li>\n<li class=\"l2\"><mark class=\"hl lab\"><b>Valvular AFib (Moderate-to-Severe Mitral Stenosis OR Mechanical Heart Valve):</b></mark> <mark class=\"hl lab\"><b>WARFARIN ONLY</b></mark> (target <mark class=\"hl mech\"><b>INR 2.0–3.0</b></mark> ; 2.5–3.5 for mechanical mitral valve) — <b>DOACs are CONTRAINDICATED!</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>B — Better Symptom Control (Rate vs. Rhythm Control):</b></span></p>\n<ul>\n<li class=\"l2\"><b>Rate Control (Target resting HR &lt; 110 bpm lenient, or &lt; 80 bpm if symptomatic):</b></li>\n<li class=\"l1\"><i>Normal EF:</i> <b>Beta-blockers</b> (Metoprolol, Bisoprolol) OR <b>Non-DHP CCBs</b> (<mark class=\"hl rx\"><b> Diltiazem, Verapamil</b></mark> ).</li>\n<li class=\"l1\"><i>HFrEF (Low EF):</i> <b>Beta-blockers</b> and/or <mark class=\"hl rx\"><b>Digoxin</b></mark> (or <mark class=\"hl rx\"><b>IV Amiodarone</b></mark> acutely) — <i>AVOID Diltiazem/Verapamil in HFrEF!</i></li>\n<li class=\"l2\"><b>Rhythm Control</b> (Preferred in young patients, first episode, symptomatic despite rate control, or HF):</li>\n<li class=\"l1\"><i>CRITICAL RULE:</i> If AFib duration <b>&gt; 48 hours or unknown</b>, <b>DO NOT cardiovert</b> until anticoagulated for <b>≥ 3 weeks</b> OR <b>TEE</b> (Transesophageal Echo) rules out LA appendage thrombus! (Also anticoagulate ≥ 4 weeks <i>after</i> cardioversion!).</li>\n<li class=\"l1\"><i>Pharmacologic Cardioversion:</i> <b>Flecainide/Propafenone</b> (ONLY if NO structural heart disease/CAD!) or <mark class=\"hl rx\"><b>Amiodarone</b></mark> (safe in structural heart disease/HF).</li>\n<li class=\"l1\"><i>Long-term:</i> Catheter <b>Pulmonary Vein Isolation (Ablation)</b>.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>C — Comorbidities:</b> Control HTN, obesity, OSA, thyroid disease, HF.</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u65\">← Case 15</button><button class=\"nv\" data-u=\"u67\">Case 17 →</button></nav></article><article class=\"view unit\" id=\"u67\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 17</span><h1>Supraventricular Tachycardia (PSVT / AVNRT)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Supraventricular+Tachycardia+%28PSVT+%2F+AVNRT%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Abrupt-onset and abrupt-offset <b>regular narrow-complex tachycardia</b> (typically HR <b>150–250 bpm</b>) originating above the ventricles, most commonly due to <b>AVNRT </b>(Atrioventricular Nodal Reentrant Tachycardia, ~60%) or <b>AVRT</b> (Atrioventricular Reentrant Tachycardia via an accessory pathway, e.g., <b>WPW</b> [Wolff-Parkinson-White] Syndrome).</p><h3><b>2. Clinical Picture</b></h3><ul>\n<li class=\"l1\">Sudden-onset rapid palpitations (\"heart pounding in neck\" — <b>frog sign</b> from simultaneous atrial/ventricular contraction), anxiety, lightheadedness, dyspnea, chest discomfort, polyuria (ANP release).</li>\n<li class=\"l1\">Classic in young, otherwise healthy adults; triggered by caffeine, stress, sleep deprivation, or bending over.</li>\n</ul><h3><b>3. Investigations</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>12-Lead ECG:</b></mark> <b>Regular, Narrow-QRS (&lt; 120 ms) Tachycardia</b>, HR 150–220 bpm; P waves are typically <b>buried inside QRS</b> or seen as pseudo-r' in V1 / pseudo-S in inferior leads.</li>\n<li class=\"l1\"><i>Baseline ECG (when in sinus rhythm):</i> Check for <b>WPW Syndrome Triad</b> -&gt; <b>Short PR interval (&lt; 120 ms)</b> + <b>Delta wave</b> (slurred upstroke of QRS) + widened QRS!</li>\n</ul><h3><b>4. Treatment (Step-by-Step Acute Termination)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Unstable (Hypotension, Shock, Chest Pain, Acute Pulmonary Edema):</b> <mark class=\"hl rx\"><b>Immediate Synchronized Cardioversion</b></mark> (50–100 J).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Stable Patient:</b></span></p>\n<ul>\n<li class=\"l2\"><b>Step 1 — Vagal Maneuvers:</b> <b>Modified Valsalva Maneuver</b> (blow forcefully into a 10 mL syringe for 15 seconds while seated, then immediately lie flat with legs raised 45° — ~40% success!) or <b>Carotid Sinus Massage</b> (exclude carotid bruits/stroke history first!).</li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>Step 2 — IV Adenosine (Drug of Choice):</b></mark> <b>6 mg rapid IV push</b> into large proximal vein followed IMMEDIATELY by <b>20 mL Normal Saline flush</b>; if no response in 1–2 min, give <b>12 mg</b> (can repeat 12 mg once).</li>\n<li class=\"l1\"><i>Warn patient:</i> <i>\"You will feel a brief 5-second sense of chest tightness/impending doom.\"</i></li>\n<li class=\"l1\"><i>Contraindicated in:</i> Severe <mark class=\"hl lab\"><b>Asthma / COPD</b></mark> (bronchospasm!), 2nd/3rd-degree AV block.</li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>Step 3 — If Adenosine Fails:</b></mark> <mark class=\"hl rx\"><b>IV Verapamil / Diltiazem</b></mark> OR <b>IV Beta-blocker</b> (Metoprolol/Esmolol).</li>\n<li class=\"l2\"><b>CRITICAL WPW WARNING:</b> In a patient with <mark class=\"hl lab\"><b>WPW + AFib</b></mark> (irregular, very fast wide-complex tachycardia with varying QRS!), <mark class=\"hl rx\"><b>AVOID AV-nodal blockers (Adenosine, Verapamil, Diltiazem, Digoxin, Beta-blockers)</b></mark> — they force all impulses down the accessory pathway causing <b>VF</b>! Use <b>Procainamide / Ibutilide </b>or <mark class=\"hl rx\"><b>Synchronized Cardioversion</b></mark> !</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Definitive Cure (&gt; 95% success):</b> <b>Electrophysiology Study (EPS) + Radiofrequency Catheter Ablation</b>.</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u66\">← Case 16</button><button class=\"nv\" data-u=\"u68\">Case 18 →</button></nav></article><article class=\"view unit\" id=\"u68\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 18</span><h1>Ventricular Tachycardia (VT) &amp; Ventricular Fibrillation (VF)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Ventricular+Tachycardia+%28VT%29+%26+Ventricular+Fibrillation+%28VF%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><ul>\n<li class=\"l1\"><b>VT</b> (Ventricular Tachycardia): <b>≥ 3 consecutive wide QRS complexes (≥ 120 ms)</b> at a rate <b>&gt; 100 bpm</b> originating below the bundle of His (<i>Sustained VT</i> &gt; 30 sec or causing instability).</li>\n<li class=\"l1\"><b>VF</b> (Ventricular Fibrillation): Chaotic, disorganized ventricular electrical activity producing <b>zero cardiac output</b> (cardiac arrest!).</li>\n</ul><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Structural / Ischemic Heart Disease (#1 Cause!):</b> Acute <mark class=\"hl lab\"><b>MI</b></mark> , old myocardial scar (<mark class=\"hl lab\"><b> CAD</b></mark> ), <b>HFrEF</b>, <mark class=\"hl lab\"><b>HCM</b></mark> , <b>ARVD</b> (Arrhythmogenic Right Ventricular Dysplasia).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Electrolyte &amp; Metabolic Triggers:</b> Severe <b>Hypokalemia</b>, <b>Hypomagnesemia</b>, Severe Hypoxia, Acidosis.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Channelopathies &amp; Drug Toxicity:</b> <b>Long QT Syndrome</b> (congenital or acquired from <i>Amiodarone, Haloperidol, Macrolides, Fluoroquinolones, Ondansetron, TCAs</i> -&gt; causes <b>Torsades de Pointes</b>!), <mark class=\"hl lab\"><b>Brugada Syndrome</b></mark> , Digoxin toxicity.</span></p><h3><b>3. Clinical Picture &amp; ECG Clues</b></h3><ul>\n<li class=\"l1\"><b>Pulseless VT / VF:</b> Unresponsive, absent pulse, absent breathing -&gt; <b>CARDIAC ARREST!</b></li>\n<li class=\"l1\"><b>VT with Pulse:</b> Palpitations, hypotension, chest pain, dyspnea, syncope (or transiently stable).</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>ECG Rule:</b></mark> <mark class=\"hl lab\"><b>Any regular wide-complex tachycardia in an adult with known CAD/HF is VT until proven otherwise!</b></mark></li>\n<li class=\"l2\"><i>VT Clues (Brugada Criteria):</i> <b>AV dissociation</b> (pathognomonic!), <b>Fusion beats</b>, <b>Capture beats</b>, <b>Concordance</b> (all V1–V6 either positive or negative), extreme axis deviation.</li>\n<li class=\"l2\"><i>Torsades de Pointes:</i> Polymorphic VT with QRS complexes \"twisting around the baseline\" in setting of <b>prolonged QTc</b>.</li>\n</ul><h3><b>4. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Pulseless VT or VF:</b> <mark class=\"hl rx\"><b>Immediate High-Quality CPR + Unsynchronized Defibrillation (Shock)</b></mark> + Epinephrine + Amiodarone (<b>ACLS</b> Shockable Rhythm protocol — see Case 30!).</li>\n<li class=\"l1\"><b>VT with a Pulse — UNSTABLE (Hypotension, Shock, Chest Pain, Altered Mental Status):</b></li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>Immediate Synchronized Cardioversion</b></mark> (100–200 J biphasic; give sedation if conscious).</li>\n<li class=\"l1\"><b>Monomorphic VT with a Pulse — STABLE:</b></li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>IV Amiodarone</b></mark> (150 mg IV over 10 min, then 1 mg/min infusion) OR <b>IV Procainamide</b> / <mark class=\"hl rx\"><b>Lidocaine</b></mark> .</li>\n<li class=\"l1\"><b>Torsades de Pointes (Polymorphic VT + Long QT):</b></li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>IV Magnesium Sulfate 2 g</b></mark> over 10–15 min (first-line even if serum Mg++ is normal!), stop QT-prolonging drugs, correct K+ (&gt; 4.0 mEq/L); if unstable -&gt; <b>Defibrillate</b>!</li>\n<li class=\"l1\"><b>Secondary Prevention:</b> <b>ICD</b> (Implantable Cardioverter-Defibrillator) + treat underlying ischemia/HF.</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u67\">← Case 17</button><button class=\"nv\" data-u=\"u69\">Case 19 →</button></nav></article><article class=\"view unit\" id=\"u69\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 19</span><h1>Bradyarrhythmias &amp; Atrioventricular (AV) Blocks</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Bradyarrhythmias+%26+Atrioventricular+%28AV%29+Blocks\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; ECG Classification</b></h3><p>Symptomatic bradycardia (<b>HR &lt; 60 bpm</b>, usually &lt; 50 bpm) or conduction delay/failure from atria to ventricles:</p>\n<ul>\n<li class=\"l1\"><b>1st-Degree AV Block:</b> Prolonged <b>PR interval &gt; 200 ms</b> (every P wave conducts; benign).</li>\n<li class=\"l1\"><b>2nd-Degree AV Block — Mobitz Type I (Wenckebach):</b> <b>Progressive PR prolongation</b> until a <b>QRS is dropped</b>, then cycle resets (AV node level; often benign/inferior MI).</li>\n<li class=\"l1\"><b>2nd-Degree AV Block — Mobitz Type II:</b> <b>Constant PR interval</b> with <b>suddenly dropped QRS complexes</b> (His-Purkinje level; <b>HIGH RISK</b> of progression to complete heart block!).</li>\n<li class=\"l1\"><b>3rd-Degree (Complete) AV Block:</b> <b>Complete AV dissociation</b> — P waves march regularly and QRS complexes march regularly, <b>completely independent of each other</b>! (Escape rhythm: narrow if junctional 40–60 bpm; wide if ventricular 20–40 bpm).</li>\n</ul><h3><b>2. Etiology (Separated — Reversible vs. Irreversible)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Reversible Causes (ALWAYS RULE OUT FIRST!):</b></span></p>\n<ul>\n<li class=\"l2\"><b>Drugs:</b> <b>Beta-blockers</b>, <mark class=\"hl rx\"><b>Diltiazem/Verapamil</b></mark> , <mark class=\"hl rx\"><b>Digoxin</b></mark> , Amiodarone, Clonidine.</li>\n<li class=\"l2\"><b>Acute Ischemia:</b> <mark class=\"hl lab\"><b>Inferior STEMI</b></mark> (vagal/AV nodal ischemia — usually transient) vs. <mark class=\"hl lab\"><b>Anterior STEMI</b></mark> (extensive septal necrosis -&gt; Mobitz II / 3rd-degree block — poor prognosis!).</li>\n<li class=\"l2\"><b>Electrolytes / Metabolic:</b> <b>Hyperkalemia</b>, Hypothyroidism, Hypothermia.</li>\n<li class=\"l2\"><b>Infections / Infiltrative:</b> <b>Infective Endocarditis</b> (aortic root abscess!), Lyme disease, Myocarditis.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Irreversible Causes:</b> Age-related idiopathic degeneration/fibrosis of conduction system (<b>Lev’s / Lenègre’s disease</b>), post-valve surgery.</span></p><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\">Fatigue, dizziness, presyncope, <b>syncope (Stokes-Adams attacks)</b>, angina, worsening heart failure, <b>Cannon \"a\" waves</b> in JVP (in 3rd-degree block).</li>\n</ul><h3><b>4. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Asymptomatic 1st-Degree or Mobitz Type I:</b> Observation only; stop offending drugs.</li>\n<li class=\"l1\"><b>Symptomatic Bradycardia (Hypotension, Altered Mental Status, Chest Pain, Shock, Acute HF):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl rx\"><b>IV Atropine 1 mg</b></mark> bolus every 3–5 min (max 3 mg). <i>(Note: Often INEFFECTIVE in Mobitz II and infranodal 3rd-degree AV block!)</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl rx\"><b>If Atropine Fails:</b></mark> <b>Transcutaneous Pacing (TCP)</b> immediately, OR <mark class=\"hl rx\"><b>IV Epinephrine (2–10 mcg/min)</b></mark> / <mark class=\"hl rx\"><b>IV Dopamine (5–20 mcg/kg/min)</b></mark> infusion.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Bridge:</b> <b>Temporary Transvenous Pacemaker</b>.</span></p>\n<ul>\n<li class=\"l1\"><b>Definitive Treatment for Irreversible Mobitz Type II, 3rd-Degree AV Block, or Symptomatic Sick Sinus Syndrome:</b> <b>Permanent Pacemaker (PPM)</b> implantation!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u68\">← Case 18</button><button class=\"nv\" data-u=\"u70\">Case 20 →</button></nav></article><article class=\"view unit\" id=\"u70\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 20</span><h1>Syncope (DIAGNOSTIC APPROACH)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Syncope+%28DIAGNOSTIC+APPROACH%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Transient, self-limited <b>loss of consciousness (TLOC)</b> with loss of postural tone caused by <b>transient global cerebral hypoperfusion</b>, characterized by rapid onset, short duration, and <b>spontaneous complete recovery</b>.</p><h3><b>2. Etiology (Separated into 3 Major Categories)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Reflex (Neurally Mediated) Syncope (~50–60% — Most Common &amp; Benign):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Vasovagal:</i> Triggered by fear, pain, blood sight, prolonged standing in hot crowded places; <b>prodrome</b> of nausea, diaphoresis, pallor, tunnel vision.</li>\n<li class=\"l2\"><i>Situational:</i> Cough, micturition, defecation, swallowing.</li>\n<li class=\"l2\"><i>Carotid Sinus Hypersensitivity:</i> Tight collar, shaving (elderly).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Orthostatic Hypotension (~15%):</b> Drop in <mark class=\"hl lab\"><b>SBP ≥ 20 mmHg or DBP ≥ 10 mmHg within 3 minutes of standing</b></mark> :</span></p>\n<ul>\n<li class=\"l2\">Volume depletion (bleeding, dehydration), Drugs (<b>Alpha-blockers [Tamsulosin], Diuretics, Vasodilators, Antidepressants</b>), Autonomic neuropathy (<b>Diabetes</b>, Parkinson’s).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Cardiac Syncope (~10–20% — HIGHEST MORTALITY!):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Arrhythmic:</i> <b>VT/VF</b>, <b>3rd-Degree AV Block</b>, Sick Sinus Syndrome, Brugada/Long QT.</li>\n<li class=\"l2\"><i>Structural:</i> <b>Severe Aortic Stenosis</b>, <mark class=\"hl lab\"><b>HCM</b></mark> , <b>Massive PE</b>, Cardiac Tamponade, Myxoma.</li>\n</ul><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ 3. Red Flags Requiring Urgent Admission (San Francisco / ESC High-Risk Criteria)</b></mark></p></div></div><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><ul>\n<li class=\"l1\">Syncope <b>during exertion</b> or <b>while supine</b>.</li>\n<li class=\"l1\">Preceded by <b>chest pain or palpitations</b> (or <b>no prodrome</b> -&gt; sudden collapse with facial trauma!).</li>\n<li class=\"l1\">Family history of <b>Sudden Cardiac Death (&lt; 40–50 yrs)</b>.</li>\n<li class=\"l1\">Abnormal <mark class=\"hl mech\"><b>ECG</b></mark> , structural heart disease / <b>HF</b>, anemia/GI bleed.</li>\n</ul></div></div><h3><b>4. Investigations &amp; Management</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Mandatory in ALL Syncope Patients:</b></mark> Detailed history (+ eyewitness account!), Orthostatic vitals, Cardiac exam, <mark class=\"hl mech\"><b>12-Lead ECG</b></mark> !</li>\n<li class=\"l1\"><i>Targeted:</i> <mark class=\"hl mech\"><b>Echocardiogram</b></mark> (if murmur/structural suspected), <mark class=\"hl mech\"><b>24–48 hr Holter / Patch / Loop Recorder</b></mark> (if arrhythmic suspected), Tilt-table test (rarely needed), <mark class=\"hl mech\"><b>D-dimer / CTPA</b></mark> (if PE suspected), Fingerstick glucose. <i>(Routine CT Brain or EEG is NOT indicated unless true seizure or head trauma!)</i></li>\n<li class=\"l1\"><b>Treatment:</b> Vasovagal -&gt; reassurance, hydration/salt, <b>physical counter-pressure maneuvers</b> (leg crossing, handgrip), lie down at prodrome; Orthostatic -&gt; stop/adjust culprit drugs, slow rising, compression stockings; Cardiac -&gt; treat arrhythmia (PPM/ICD) or structural lesion (AVR for AS).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u69\">← Case 19</button><button class=\"nv\" data-u=\"u71\">Case 21 →</button></nav></article><article class=\"view unit\" id=\"u71\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 21</span><h1>Acute Rheumatic Fever (ARF) &amp; Chronic Rheumatic Heart Disease (RHD)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Rheumatic+Fever+%28ARF%29+%26+Chronic+Rheumatic+Heart+Disease+%28RHD%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>ARF:</b></mark> Autoimmune, multi-system inflammatory disorder occurring <b>2–4 weeks</b> after untreated <b>GAS</b> (Group A Beta-Hemolytic <i>Streptococcus</i>) <b>pharyngitis</b>, primarily affecting children aged <b>5–15 years</b> (still highly prevalent in Egypt!).</li>\n<li class=\"l1\"><b>RHD:</b> Permanent valvular damage (<b>Mitral &gt; Aortic</b> &gt; Tricuspid) resulting from recurrent/severe ARF episodes.</li>\n</ul><h3><b>2. Pathophysiology</b></h3><p><b>Molecular mimicry:</b> Antibodies directed against <i>Streptococcus pyogenes</i> <b>M-protein</b> cross-react with human cardiac myosin/valve endothelium, synovium, basal ganglia, and skin.</p><h3><b>3. Clinical Picture &amp; Diagnosis (Revised Jones Criteria — 2015 AHA)</b></h3><p>Requires <b>Evidence of Preceding GAS Infection</b> (<b>Elevated ASOT</b> [Anti-Streptolysin O Titer] / Anti-DNase B, positive throat culture, or rapid strep test) <b>PLUS</b>: <b>2 Major Criteria</b> OR <b>1 Major + 2 Minor Criteria</b>.</p>\n<ul>\n<li class=\"l1\"><b>5 MAJOR Criteria (Mnemonic: \"JONES\"):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>J</b>oints: <b>Migratory Polyarthritis</b> of large joints (knees, ankles, elbows, wrists — excruciating pain, responds dramatically to <mark class=\"hl rx\"><b>Aspirin within 24–48 hrs!</b></mark> ; note: <i>monoarthritis</i> counts in high-risk endemic populations like Egypt!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>O</b> (Heart shape) — <b>Carditis</b> (Clinical or Subclinical on Echo): Pancarditis (<b>Mitral regurgitation</b> = most common acute murmur; <b>Carey Coombs</b> mid-diastolic murmur; pericarditis; heart failure).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>N</b>odules: <b>Subcutaneous Nodules</b> (painless, firm over extensor surfaces/bony prominences — associated with severe carditis).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>E</b>rythema Marginatum: Painless, non-pruritic pink rings with central clearing on trunk/proximal limbs (spares face).</span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><b>S</b>ydenham Chorea (\"St. Vitus Dance\"): Late manifestation (1–6 months post-GAS!); involuntary purposeless jerky movements, emotional lability, <b>\"milkmaid's grip\"</b>.</span></p>\n<ul>\n<li class=\"l1\"><b>4 MINOR Criteria (Mnemonic: \"FEAR\"):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>F</b>ever (≥ 38.0–38.5°C).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>E</b>levated <mark class=\"hl mech\"><b>ESR</b></mark> (≥ 30–60 mm/hr) or <mark class=\"hl mech\"><b>CRP</b></mark> (≥ 3.0 mg/dL).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>A</b>rthralgia (polyarthralgia).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>R</b>educed conduction -&gt; <b>Prolonged PR interval</b> on ECG.</span></p><h3><b>4. Treatment &amp; Long-Term Prophylaxis</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Eradicate GAS (Even if throat culture negative):</b> Single <b>IM Benzathine Penicillin G</b> (1.2 million U if &gt; 27 kg; 600,000 U if ≤ 27 kg) OR 10 days oral Penicillin V / Amoxicillin (Azithromycin if penicillin-allergic).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Anti-Inflammatory:</b></span></p>\n<ul>\n<li class=\"l2\"><i>Arthritis only:</i> <mark class=\"hl rx\"><b>High-dose Aspirin</b></mark> (or Naproxen).</li>\n<li class=\"l2\"><i>Moderate-to-Severe Carditis / Heart Failure:</i> <mark class=\"hl rx\"><b>Oral Prednisone</b></mark> (1–2 mg/kg/day for 2–4 weeks, tapered while overlapping Aspirin) + HF therapy.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Secondary Prophylaxis (CRITICAL TO PREVENT RHD! — IM Benzathine Penicillin G every 3–4 weeks):</b></span></p>\n<ul>\n<li class=\"l2\"><i>ARF WITHOUT Carditis:</i> For <b>5 years or until age 21</b> (whichever is longer).</li>\n<li class=\"l2\"><i>ARF WITH Carditis (no residual valve disease):</i> For <b>10 years or until age 21</b>.</li>\n<li class=\"l2\"><i>ARF WITH Persistent Valvular RHD:</i> For <b>10 years or until age 40</b> (often <b>lifelong</b>!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u70\">← Case 20</button><button class=\"nv\" data-u=\"u72\">Case 22 →</button></nav></article><article class=\"view unit\" id=\"u72\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 22</span><h1>Dilated Cardiomyopathy (DCM) &amp; Peripartum Cardiomyopathy (PPCM)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Dilated+Cardiomyopathy+%28DCM%29+%26+Peripartum+Cardiomyopathy+%28PPCM%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><ul>\n<li class=\"l1\"><b>DCM:</b> Ventricular dilation and systolic dysfunction (<b>LVEF &lt; 40%</b>) in the absence of severe CAD or abnormal loading conditions.</li>\n<li class=\"l1\"><b>PPCM:</b> Idiopathic HFrEF (<b>LVEF &lt; 45%</b>) presenting toward the <b>end of pregnancy (last month)</b> or within <b>5 months postpartum</b> in a woman without prior heart disease!</li>\n</ul><h3><b>2. Etiology of DCM (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Genetic / Familial (~30–40%):</b> Titin (<i>TTN</i>) mutations.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Infectious / Post-Inflammatory:</b> Post-viral <b>Myocarditis</b> (Coxsackie B, Parvovirus B19, COVID-19), HIV.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Toxic / Drug-Induced:</b> Chronic <b>Alcohol</b> abuse, Chemotherapy (<b>Doxorubicin/Anthracyclines</b>, <b>Trastuzumab</b>), Cocaine.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Endocrine / Metabolic / Stress:</b> <b>Peripartum (PPCM)</b>, Thyrotoxicosis, Pheochromocytoma, <b>Takotsubo (\"Broken Heart\") Cardiomyopathy</b> (transient apical ballooning after severe emotional/physical stress), Tachycardia-induced (incessant AFib).</span></p><h3><b>3. Clinical Picture &amp; Investigations</b></h3><ul>\n<li class=\"l1\">Symptoms/signs of <b>biventricular Heart Failure</b> (dyspnea, orthopnea, edema, S3 gallop, functional MR/TR).</li>\n<li class=\"l1\"><b>Workup:</b> <mark class=\"hl mech\"><b>Echocardiogram</b></mark> (4-chamber dilation, global hypokinesia, LVEF &lt; 40%, check for <b>LV mural thrombus</b>!), <mark class=\"hl mech\"><b>ECG</b></mark> , <b>Coronary Angiography</b> (to rule out ischemic cardiomyopathy), <mark class=\"hl mech\"><b>Cardiac MRI</b></mark> (detects fibrosis/myocarditis), <mark class=\"hl mech\"><b>TSH</b></mark> , Iron panel (rule out hemochromatosis).</li>\n</ul><h3><b>4. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Standard 4-Pillar HFrEF GDMT</b> (see Case 8) + Diuretics + ICD/CRT if LVEF ≤ 35%.</li>\n<li class=\"l1\"><b>Special PPCM Notes:</b></li>\n<li class=\"l2\"><i>During pregnancy:</i> <b>SAFE</b> drugs = <mark class=\"hl rx\"><b>Hydralazine + Isosorbide Dinitrate</b></mark> , <b>Beta-blockers</b> (Metoprolol/Labetalol), <mark class=\"hl rx\"><b>Furosemide</b></mark> , Digoxin. (<mark class=\"hl rx\"><b> STRICTLY AVOID ACE-i, ARBs, ARNI, Spironolactone during pregnancy!</b></mark> ).</li>\n<li class=\"l2\"><i>Postpartum:</i> Can switch to standard GDMT (Enalapril/Captopril compatible with breastfeeding); consider <b>Bromocriptine</b> (inhibits prolactin cleavage) + anticoagulation if LVEF &lt; 35%. Warn against future pregnancies if LVEF fails to recover!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u71\">← Case 21</button><button class=\"nv\" data-u=\"u73\">Case 23 →</button></nav></article><article class=\"view unit\" id=\"u73\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 23</span><h1>Hypertrophic Cardiomyopathy (HCM)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hypertrophic+Cardiomyopathy+%28HCM%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Autosomal dominant genetic disorder of cardiac sarcomere proteins (e.g., <i>MYH7</i>, <i>MYBPC3</i>) causing <b>unexplained asymmetric Left Ventricular Hypertrophy</b> (wall thickness <b>≥ 15 mm</b>, typically <b>interventricular septum</b>) without a secondary cause (like HTN or AS). <b>#1 cause of Sudden Cardiac Death (SCD) in young athletes!</b></p><h3><b>2. Pathophysiology</b></h3><p>Asymmetric septal hypertrophy -&gt; <b>LVOT</b> (Left Ventricular Outflow Tract) dynamic obstruction (<b>SAM</b> — Systolic Anterior Motion of anterior mitral leaflet) + diastolic dysfunction + myocardial fibrosis (ventricular arrhythmias).</p><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\">Often asymptomatic until <b>SCD</b>! May present with <b>exertional dyspnea</b>, <b>angina</b>, <b>palpitations</b>, or <b>exertional syncope</b>.</li>\n<li class=\"l1\"><b>Classic Dynamic Auscultation:</b> <b>Harsh systolic crescendo-decrescendo murmur</b> at <b>Left Lower Sternal Border</b> (does NOT radiate to carotids!):</li>\n<li class=\"l2\"><b>INCREASES</b> with maneuvers that <b>DECREASE preload/LV volume</b>: <b>Standing up abruptly</b> &amp; <b>Valsalva maneuver</b>!</li>\n<li class=\"l2\"><b>DECREASES</b> with maneuvers that <b>INCREASE preload/afterload</b>: <b>Squatting</b>, <b>Passive leg raise</b>, <b>Handgrip</b>!</li>\n</ul><h3><b>4. Investigations &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>ECG:</b></mark> Marked <b>LVH</b>, deep narrow <b>\"dagger-like\" Q waves</b> in lateral/inferior leads.</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Echocardiogram (Diagnostic):</b></mark> Asymmetric septal hypertrophy (septal:posterior wall ratio &gt; 1.3–1.5), <b>SAM</b>, LVOT gradient (<b>≥ 30 mmHg</b> = obstructive).</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Cardiac MRI</b></mark> (late gadolinium enhancement assesses SCD fibrosis risk).</li>\n<li class=\"l1\"><b>Management:</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>AVOID competitive/intense sports</b> &amp; <mark class=\"hl rx\"><b>AVOID dehydration, Digoxin, and pure vasodilators (Nitrates/Amlodipine)</b></mark> (all worsen LVOT obstruction!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>First-Line Medical:</b> <b>Beta-blockers</b> (Metoprolol, Propranolol) or <mark class=\"hl rx\"><b>Verapamil</b></mark> (slows HR, increases diastolic filling, reduces contractility) + <b>Mavacamten</b> (cardiac myosin inhibitor) or Disopyramide.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>ICD Implantation:</b> Mandatory for <b>SCD prevention</b> if prior arrest/VT, family history of SCD, unexplained syncope, massive LVH ≥ 30 mm, or extensive MRI fibrosis.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Septal Reduction (Refractory obstructive symptoms):</b> <b>Surgical Septal Myectomy</b> or <b>Alcohol Septal Ablation</b>.</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u72\">← Case 22</button><button class=\"nv\" data-u=\"u74\">Case 24 →</button></nav></article><article class=\"view unit\" id=\"u74\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 24</span><h1>Acute Myocarditis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Myocarditis\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Inflammation of the myocardium causing myocyte necrosis in the absence of coronary ischemia.</p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Viral (Most Common):</b> Coxsackievirus B, Parvovirus B19, Adenovirus, Influenza, <b>SARS-CoV-2 (COVID-19)</b>, HIV.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Non-Viral Infections:</b> Diphtheria toxin, Lyme disease, Chagas disease, Rheumatic carditis.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Autoimmune / Hypersensitivity / Toxins:</b> <mark class=\"hl lab\"><b>SLE</b></mark> , Giant Cell Myocarditis (fulminant!), <mark class=\"hl lab\"><b>Drug hypersensitivity (DRESS)</b></mark> , Checkpoint inhibitors, COVID-19 mRNA vaccine (rare, mild, young males).</span></p><h3><b>3. Clinical Picture &amp; Investigations</b></h3><ul>\n<li class=\"l1\">Young patient presenting <b>1–2 weeks after a viral URTI or gastroenteritis</b> with <b>chest pain</b> (often pleuritic/pericarditic), <b>unexplained sinus tachycardia</b>, dyspnea/new HF, arrhythmias, or sudden death (<mark class=\"hl lab\"><b> mimics STEMI!</b></mark> ).</li>\n<li class=\"l1\"><b>Labs:</b> Elevated <mark class=\"hl mech\"><b>Cardiac Troponin</b></mark> , elevated <mark class=\"hl mech\"><b>CRP/ESR</b></mark> , BNP.</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>ECG:</b></mark> Sinus tachycardia, diffuse ST-T changes, or <mark class=\"hl lab\"><b>focal ST elevation mimicking STEMI</b></mark> !</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Echocardiogram:</b></mark> New regional or global LV dysfunction.</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Rule Out CAD:</b></mark> Coronary Angiography or <b>CCTA</b> (shows <b>CLEAN coronary arteries!</b>).</li>\n<li class=\"l1\"><b>Gold Standard Non-Invasive Test:</b> <mark class=\"hl mech\"><b>Cardiac MRI</b></mark> (Lake Louise Criteria: myocardial edema + non-ischemic late gadolinium enhancement).</li>\n</ul><h3><b>4. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Supportive HF GDMT</b> (ACE-i/ARB, Beta-blockers, Diuretics) + <b>Strict Restriction from Competitive Sports/Exercise for 3–6 Months</b> (exercise triggers fatal arrhythmias!).</li>\n<li class=\"l1\"><mark class=\"hl rx\"><b>AVOID NSAIDs</b></mark> if myocardial dysfunction is present (worsen inflammation/mortality in viral myocarditis!).</li>\n<li class=\"l1\">Fulminant/Cardiogenic shock -&gt; <b>ICU</b>, inotropes, <b>ECMO / MCS</b> (Mechanical Circulatory Support); Corticosteroids/Immunosuppression reserved ONLY for Giant Cell Myocarditis, Eosinophilic myocarditis, or Autoimmune disease.</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u73\">← Case 23</button><button class=\"nv\" data-u=\"u75\">Case 25 →</button></nav></article><article class=\"view unit\" id=\"u75\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 25</span><h1>Acute Aortic Dissection</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Aortic+Dissection\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Catastrophic tear in the aortic intima allowing high-pressure blood to dissect into the aortic media, creating a <b>false lumen</b>. <b>Mortality increases ~1–2% per hour if untreated!</b></p><h3><b>2. Classification (Stanford — Guides Management!)</b></h3><ul>\n<li class=\"l1\"><b>Type A (~60%):</b> Involves <b>Ascending Aorta</b> -&gt; <b>SURGICAL EMERGENCY!</b></li>\n<li class=\"l1\"><b>Type B (~40%):</b> Confined to <b>Descending Aorta</b> (distal to left subclavian artery) -&gt; <b>Medical Management</b> (unless complicated by rupture/malperfusion -&gt; <b>TEVAR</b>).</li>\n</ul><h3><b>3. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Chronic Uncontrolled Hypertension (~75% — #1 Risk Factor!).</b></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Connective Tissue Disorders (Young patients):</b> <b>Marfan Syndrome</b>, Ehlers-Danlos Syndrome, Loeys-Dietz, <b>Bicuspid Aortic Valve</b>.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Other:</b> Cocaine/amphetamine use, Aortic trauma (deceleration), Pregnancy (3rd trimester), Aortitis.</span></p><h3><b>4. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Sudden, maximal-at-onset \"tearing\" or \"ripping\" chest/interscapular back pain</b> (unlike MI pain which builds up over minutes!).</li>\n<li class=\"l1\"><b>Pulse Deficit &amp; BP Discrepancy (&gt; 20 mmHg between right and left arms)</b>.</li>\n<li class=\"l1\"><b>Extension Complications:</b></li>\n<li class=\"l2\">Retrograde into Aortic Valve -&gt; <b>Acute Aortic Regurgitation</b> (early diastolic murmur + pulmonary edema).</li>\n<li class=\"l2\">Into Pericardium -&gt; <mark class=\"hl lab\"><b>Cardiac Tamponade</b></mark> (hypotension + JVD).</li>\n<li class=\"l2\">Into <b>RCA</b> -&gt; <mark class=\"hl lab\"><b>Inferior STEMI</b></mark> !</li>\n<li class=\"l2\">Into Carotids -&gt; <mark class=\"hl lab\"><b>Acute Stroke</b></mark> ; Into Renal/Mesenteric -&gt; <mark class=\"hl lab\"><b>AKI / Bowel Ischemia</b></mark> .</li>\n</ul><h3><b>5. Investigations &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><b>Imaging:</b> <mark class=\"hl mech\"><b>CT Angiography (CTA) of Chest/Abdomen</b></mark> (Gold standard in stable patients — shows intimal flap &amp; true/false lumens!); <b>Bedside TEE</b> (if unstable to move). <i>(CXR may show </i><i><b>widened mediastinum &gt; 8 cm</b></i><i> — normal CXR does NOT exclude dissection!).</i></li>\n<li class=\"l1\"><b>CRITICAL ER RULE:</b> <mark class=\"hl rx\"><b>NEVER give Anticoagulants (Heparin) or Thrombolytics if Dissection is suspected!</b></mark></li>\n<li class=\"l1\"><b>Immediate Medical Stabilization (\"Anti-Impulse Therapy\" — Lower Wall Shear Stress FIRST!):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Control Heart Rate FIRST (&lt; 60 bpm):</b> <b>IV Esmolol</b> or <mark class=\"hl rx\"><b>IV Labetalol</b></mark> ! <i>(NEVER give a pure vasodilator like Nitroprusside/Nicardipine BEFORE Beta-blocker — reflex tachycardia increases aortic wall shear stress and rips the dissection further!)</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Control SBP (100–120 mmHg):</b></mark> Add <b>IV Nicardipine</b> or <b>Nitroprusside</b> if BP remains high after Beta-blocker.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>IV Morphine</b> for pain (reduces sympathetic surge).</span></p>\n<ul>\n<li class=\"l1\"><b>Definitive:</b> <b>Immediate Open Cardiothoracic Surgery</b> for <b>Type A</b>; Medical +/- <b>TEVAR</b> (Thoracic Endovascular Aortic Repair) for <b>Type B</b>.</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u74\">← Case 24</button><button class=\"nv\" data-u=\"u76\">Case 26 →</button></nav></article><article class=\"view unit\" id=\"u76\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 26</span><h1>Peripheral Arterial Disease (PAD) &amp; Acute Limb Ischemia (ALI)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Peripheral+Arterial+Disease+%28PAD%29+%26+Acute+Limb+Ischemia+%28ALI%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Chronic PAD:</b></mark> Progressive atherosclerotic narrowing of lower extremity arteries reducing limb perfusion.</li>\n<li class=\"l1\"><b>Acute Limb Ischemia (ALI):</b> Sudden decrease in limb perfusion threatening limb viability within <b>6 hours</b>.</li>\n</ul><h3><b>2. Etiology (Separated)</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Chronic PAD:</b></mark> Atherosclerosis (<b>Smoking</b> &amp; <b>Diabetes</b> = strongest risk factors!, HTN, Dyslipidemia).</li>\n<li class=\"l1\"><b>ALI:</b> (1) <b>Arterial Embolism</b> (usually from heart: <mark class=\"hl lab\"><b>AFib</b></mark> , LV thrombus — <i>sudden onset, no prior claudication!</i>), (2) <b>Acute Thrombosis in situ</b> (plaque rupture on pre-existing PAD), (3) Trauma / Graft thrombosis.</li>\n</ul><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Chronic PAD:</b></mark> <b>Intermittent Claudication</b> (reproducible cramping calf/thigh/buttock pain during walking, relieved within 1–5 min of standing still), hair loss, shiny thin skin, thickened nails, <b>absent/diminished pedal pulses</b>, prolonged capillary refill, <b>Critical Limb Ischemia</b> (rest pain worse at night/relieved by dangling leg over bed, <b>punched-out painful ischemic ulcers</b> on toes/lateral malleolus, gangrene).</li>\n<li class=\"l1\"><b>ALI (</b>\"The 6 Ps\"<b>):</b> <b>P</b>ain, <b>P</b>allor, <b>P</b>ulselessness, <b>P</b>aresthesia, <b>P</b>aralysis (late — ominous!), <b>P</b>oikilothermia (cold!).</li>\n</ul><h3><b>4. Investigations &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Chronic PAD Diagnosis:</b></mark> <b>ABI</b> (Ankle-Brachial Index = Highest Ankle SBP ÷ Highest Brachial SBP):</li>\n<li class=\"l2\">0.91 – 1.30: Normal | <mark class=\"hl lab\"><b>≤ 0.90: Diagnostic of PAD</b></mark> | &lt; 0.40: Severe/Critical ischemia | &gt; 1.30: Non-compressible calcified vessels (common in diabetics -&gt; use <b>Toe-Brachial Index</b>!).</li>\n<li class=\"l2\"><b>Arterial Duplex Ultrasound</b> -&gt; <b>CTA / Angiography</b> before revascularization.</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Chronic PAD Treatment:</b></mark></li>\n<li class=\"l2\"><b>Strict Smoking Cessation</b> (#1 intervention!) + <b>Supervised Exercise Therapy</b> (walk until moderate pain, rest, repeat).</li>\n<li class=\"l2\"><b>Medical:</b> <mark class=\"hl rx\"><b>Aspirin 75–100 mg OR Clopidogrel 75 mg</b></mark> (+ low-dose Rivaroxaban 2.5 mg BID in high-risk), <mark class=\"hl rx\"><b>High-Intensity Statin</b></mark> , <b>Cilostazol</b> 100 mg BID (improves claudication distance — <i>contraindicated in HF!</i>).</li>\n<li class=\"l2\"><b>Revascularization (Endovascular Angioplasty/Stent or Bypass):</b> For disabling claudication or Critical Limb Ischemia.</li>\n<li class=\"l1\"><b>ALI Treatment (Surgical Emergency — 6-Hour Golden Window!):</b></li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>Immediate IV Unfractionated Heparin (UFH)</b></mark> bolus + infusion to prevent clot propagation!</li>\n<li class=\"l2\"><b>Emergent Vascular Surgery:</b> Catheter-directed thrombolysis or <b>Surgical Fogarty Embolectomy / Bypass</b> (amputation if irreversible paralysis/rigor mortis!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u75\">← Case 25</button><button class=\"nv\" data-u=\"u77\">Case 27 →</button></nav></article><article class=\"view unit\" id=\"u77\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 27</span><h1>Pulmonary Hypertension (PH) &amp; COR Pulmonale</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pulmonary+Hypertension+%28PH%29+%26+COR+Pulmonale\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><ul>\n<li class=\"l1\"><b>Pulmonary Hypertension (PH):</b> Mean Pulmonary Artery Pressure (<b>mPAP</b>) <b>&gt; 20 mmHg</b> on right heart catheterization.</li>\n<li class=\"l1\"><b>Cor Pulmonale:</b> Right Ventricular (<b>RV</b>) hypertrophy and/or dilation/failure secondary to pulmonary hypertension caused by <b>lung disease or hypoxia</b> (Group 3 PH — NOT left heart disease!).</li>\n</ul><h3><b>2. Etiology (Separated — WHO 5 Groups)</b></h3><ul>\n<li class=\"l1\"><b>Group 1 — PAH (Pulmonary Arterial Hypertension):</b> Idiopathic (young females), Connective tissue disease (<mark class=\"hl lab\"><b> Scleroderma</b></mark> , SLE), <b>Schistosomiasis</b> (classic in Egypt!), Congenital shunts (Eisenmenger), HIV.</li>\n<li class=\"l1\"><b>Group 2 — Left Heart Disease (#1 Overall Cause of PH!):</b> HFrEF, HFpEF, <b>Mitral Stenosis</b>, MR.</li>\n<li class=\"l1\"><b>Group 3 — Chronic Lung Disease / Hypoxia (#1 Cause of Cor Pulmonale!):</b> <mark class=\"hl lab\"><b>COPD</b></mark> , <b>ILD</b> (Interstitial Lung Disease), <mark class=\"hl lab\"><b>OSA</b></mark> , Kyphoscoliosis.</li>\n<li class=\"l1\"><b>Group 4 — CTEPH:</b> Chronic Thromboembolic PH (post-<mark class=\"hl lab\"><b> PE</b></mark> ).</li>\n<li class=\"l1\"><b>Group 5 — Miscellaneous:</b> Sarcoidosis, Sickle cell/Thalassemia.</li>\n</ul><h3><b>3. Clinical Picture &amp; Investigations</b></h3><ul>\n<li class=\"l1\">Progressive exertional dyspnea, fatigue, exertional syncope, <b>RV heave</b> (left parasternal lift), <b>loud P2</b>, <b>TR murmur</b> (holosystolic at left lower sternal border, increases on inspiration — <b>Carvallo’s sign</b>), <b>JVD</b>, hepatomegaly, ascites, peripheral edema.</li>\n<li class=\"l1\"><b>Workup:</b> <mark class=\"hl mech\"><b>Echocardiogram</b></mark> (estimates <b>PASP</b>, assesses RV size/function), <mark class=\"hl mech\"><b>ECG</b></mark> (RAD, RVH, <b>P-Pulmonale</b>), <mark class=\"hl mech\"><b>PFTs + Chest CT</b></mark> (lung disease), <b>V/Q Scan</b> (best screening for Group 4 <b>CTEPH</b>!), <b>Right Heart Catheterization</b> (Gold standard to confirm mPAP &gt; 20 mmHg and <b>PCWP</b>).</li>\n</ul><h3><b>4. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Treat Underlying Cause!</b></li>\n<li class=\"l1\"><i>Group 3 (COPD/Cor Pulmonale):</i> <b>Long-Term Home Oxygen Therapy (LTOT)</b> (&gt; 15 hrs/day if PaO2 ≤ 55 mmHg — <i>ONLY therapy proven to reduce mortality!</i>), bronchodilators, cautious diuretics for edema (<b>avoid over-diuresis</b> as RV is preload-dependent; <i>pulmonary vasodilators like Sildenafil are generally NOT recommended in Group 2 or 3!</i>).</li>\n<li class=\"l1\"><i>Group 1 (PAH):</i> Pulmonary vasodilators (<b>Sildenafil/Tadalafil [PDE-5i]</b>, <b>Bosentan/Ambrisentan [Endothelin RAs]</b>, <b>Epoprostenol</b>).</li>\n<li class=\"l1\"><i>Group 4 (CTEPH):</i> Lifelong anticoagulation + <b>Pulmonary Thromboendarterectomy</b> (curative!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u76\">← Case 26</button><button class=\"nv\" data-u=\"u78\">Case 28 →</button></nav></article><article class=\"view unit\" id=\"u78\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 28</span><h1>Dyslipidemia &amp; Cardiovascular Risk Prevention</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Dyslipidemia+%26+Cardiovascular+Risk+Prevention\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Risk Categories</b></h3><p>Disorders of lipoprotein metabolism (elevated <b>LDL-C</b> [Low-Density Lipoprotein Cholesterol], elevated <b>Triglycerides [TG]</b>, or low <b>HDL-C</b>) driving atherosclerosis.</p><h3><b>2. Secondary Causes of Dyslipidemia (Separated — ALWAYS SCREEN FIRST!)</b></h3><ul>\n<li class=\"l1\"><b>High LDL:</b> <mark class=\"hl lab\"><b>Hypothyroidism</b></mark> , Nephrotic syndrome, Cholestatic liver disease (<mark class=\"hl lab\"><b> PBC</b></mark> ), Anorexia nervosa.</li>\n<li class=\"l1\"><b>High Triglycerides:</b> Uncontrolled <b>Diabetes Mellitus</b>, Obesity, Alcohol, <mark class=\"hl lab\"><b>CKD</b></mark> , Drugs (Oral Estrogen, Corticosteroids, Thiazides, Beta-blockers, Isotretinoin).</li>\n</ul><h3><b>3. Treatment Targets &amp; Guidelines (LDL-C is Primary Target!)</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl rx\"><b>High-Intensity Statin</b></mark> (<mark class=\"hl rx\"><b> Atorvastatin 40–80 mg</b></mark> or <mark class=\"hl rx\"><b>Rosuvastatin 20–40 mg</b></mark> nightly/daily — lowers LDL by ≥ 50%) is indicated for <mark class=\"hl rx\"><b>4 Core Statin-Benefit Groups:</b></mark></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\">Clinical <b>ASCVD</b> (Prior MI, ACS, Stable Angina, Stroke/TIA, PAD) -&gt; Target <b>LDL &lt; 55 mg/dL</b> (ESC) or &lt; 70 mg/dL (ACC).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\">Severe Primary Hypercholesterolemia (<b>LDL ≥ 190 mg/dL</b> -&gt; suspect Familial Hypercholesterolemia!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Diabetes Mellitus</b> (Age 40–75 years -&gt; Moderate-to-High intensity Statin).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\">High 10-year ASCVD Risk (<b>≥ 7.5–20%</b>).</span></p>\n<ul>\n<li class=\"l1\"><mark class=\"hl rx\"><b>If LDL Goal NOT Met on Max-Tolerated Statin:</b></mark> Add <b>Ezetimibe 10 mg/day</b> (blocks intestinal cholesterol absorption), then <b>PCSK9 Inhibitor</b> (<b>Evolocumab / Alirocumab</b>).</li>\n<li class=\"l1\"><b>Severe Hypertriglyceridemia (TG ≥ 500–1,000 mg/dL -&gt; Risk of Acute Pancreatitis!):</b> Low-fat/sugar-free diet + <b>Fibrates</b> (<b>Fenofibrate</b> — <i>never combine Gemfibrozil with Statins due to rhabdomyolysis risk!</i>) + <b>Omega-3 fatty acids (Icosapent ethyl)</b>.</li>\n<li class=\"l1\"><i>Statin Side Effects:</i> Myalgia (check <b>CK</b> ONLY if symptomatic; rule out hypothyroidism/Vitamin D deficiency; switch to hydrophilic/alternate-day Rosuvastatin rather than stopping permanently!), mild asymptomatic transaminase rise (safe up to &lt; 3× ULN).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u77\">← Case 27</button><button class=\"nv\" data-u=\"u79\">Case 29 →</button></nav></article><article class=\"view unit\" id=\"u79\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 29</span><h1>Cardiogenic Shock</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cardiogenic+Shock\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Life-threatening state of critical end-organ hypoperfusion due to primary cardiac pump failure: <mark class=\"hl lab\"><b>SBP &lt; 90 mmHg</b></mark> (or requiring vasopressors to maintain SBP ≥ 90) for &gt; 30 min + signs of hypoperfusion (<b>cold clammy skin, oliguria &lt; 30 mL/hr, altered mental status, serum lactate &gt; 2 mmol/L</b>).</p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Acute Myocardial Infarction (~80% — Especially Large Anterior STEMI or Mechanical Complications: Papillary Muscle Rupture, VSR, Free Wall Rupture).</b></mark></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>End-Stage HFrEF / Acute Myocarditis / Takotsubo.</b></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Valvular Emergencies:</b> Acute severe AR or MR, critical AS, prosthetic valve thrombosis.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Refractory Arrhythmias</b> or <b>Cardiac Tamponade / Massive PE</b> (obstructive shock).</span></p><h3><b>3. Treatment (ICU Emergency!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl mech\"><b>Immediate Bedside Echo</b></mark> (assess LVEF, tamponade, acute MR/VSR, RV infarct).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl mech\"><b>Emergent Revascularization (Primary PCI or CABG):</b></mark> <b>ONLY proven mortality-reducing intervention</b> in AMI-induced cardiogenic shock!</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Hemodynamic Support:</b></span></p>\n<ul>\n<li class=\"l2\"><i>If </i><i><b>NO</b></i><i> pulmonary edema (e.g., RV MI):</i> Small cautious Normal Saline boluses (250 mL).</li>\n<li class=\"l2\"><i>First-Line Vasopressor (If SBP &lt; 80–90):</i> <mark class=\"hl rx\"><b>Norepinephrine</b></mark> infusion (preferred over Dopamine — causes fewer arrhythmias &amp; lower mortality!).</li>\n<li class=\"l2\"><i>Add Inotrope (Once BP supported to improve Cardiac Output):</i> <mark class=\"hl rx\"><b>Dobutamine</b></mark> or <b>Milrinone</b>.</li>\n<li class=\"l2\"><i>Avoid:</i> Beta-blockers, ACE-i, and aggressive diuretics while hypotensive!</li>\n</ul>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Mechanical Circulatory Support (Refractory Shock):</b> <b>Impella</b>, <b>IABP</b>, or <b>VA-ECMO</b> as bridge to recovery/transplant.</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u78\">← Case 28</button><button class=\"nv\" data-u=\"u80\">Case 30 →</button></nav></article><article class=\"view unit\" id=\"u80\" hidden style=\"--c:#7a8b00\"><button class=\"back\" data-p=\"4\">← Cardiology</button><header class=\"uh\"><span class=\"ul\">Case 30</span><h1>Cardiac Arrest &amp; Acls Reversible Causes</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cardiac+Arrest+%26+Acls+Reversible+Causes\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; 4 Arrest Rhythms</b></h3><p>Sudden cessation of effective cardiac mechanical activity and circulation (unresponsive, no breathing/gasping, <b>no carotid pulse within ≤ 10 seconds</b>).</p><table class=\"t \"><tr class=\"hd\"><th><p><b>Rhythm Category</b></p></th><th><p><mark class=\"hl mech\"><b>ECG Appearance</b></mark></p></th><th><p><mark class=\"hl rx\"><b>Immediate Shock (Defibrillation)?</b></mark></p></th><th><p><b>Key Medications</b></p></th></tr><tr><td><p><b>SHOCKABLE:</b> <b>VF</b> &amp; <b>Pulseless VT</b></p></td><td><p>Chaotic waves (VF) or fast wide QRS (pVT)</p></td><td><p><b>YES! Immediate Shock (200 J Biphasic)</b> + resume CPR 2 min!</p></td><td><p><mark class=\"hl rx\"><b>Epinephrine 1 mg IV/IO q3–5 min</b></mark> (after 2nd shock) + <mark class=\"hl rx\"><b>Amiodarone 300 mg IV</b></mark> (after 3rd shock, then 150 mg) OR Lidocaine</p></td></tr><tr><td><p><b>NON-SHOCKABLE:</b> <b>Asystole</b> &amp; <b>PEA</b></p></td><td><p>Flat line (check 2 leads!) OR organized rhythm with NO pulse</p></td><td><p><b>NO! DO NOT SHOCK!</b> Immediate High-Quality CPR!</p></td><td><p><mark class=\"hl rx\"><b>Epinephrine 1 mg IV/IO AS SOON AS POSSIBLE</b></mark> , repeat q3–5 min + <b>FIND &amp; TREAT REVERSIBLE CAUSE!</b></p></td></tr></table><h3><b>2. High-Quality CPR Targets</b></h3><ul>\n<li class=\"l1\">Rate <b>100–120 compressions/min</b>, Depth <b>5–6 cm (2–2.4 inches)</b>, Full chest recoil, Minimize interruptions (&lt; 10 sec), Avoid hyperventilation (10 breaths/min if intubated; 30:2 if bag-mask).</li>\n</ul><h3><b>3. THE 10 REVERSIBLE CAUSES OF CARDIAC ARREST (5 Hs &amp; 5 Ts — </b><b>Especially Vital in PEA!</b><b>)</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>5 Hs</b></p></th><th><p><b>Immediate Action</b></p></th><th><p><b>5 Ts</b></p></th><th><p><b>Immediate Action</b></p></th></tr><tr><td><p><b>H</b>ypovolemia</p></td><td><p>Rapid IV crystalloid / blood bolus</p></td><td><p><b>T</b>ension Pneumothorax</p></td><td><p><b>Immediate Needle Decompression</b> -&gt; Chest tube</p></td></tr><tr><td><p><b>H</b>ypoxia</p></td><td><p>Secure airway + 100% O2</p></td><td><p><b>T</b>amponade (Cardiac)</p></td><td><p><mark class=\"hl rx\"><b>Emergent Pericardiocentesis</b></mark></p></td></tr><tr><td><p><b>H</b>ydrogen ion (Acidosis)</p></td><td><p>Optimize ventilation; consider IV NaHCO3</p></td><td><p><b>T</b>oxins (Drug overdose)</p></td><td><p>Specific antidote (Naloxone, Lipid emulsion, NaHCO3 for TCAs)</p></td></tr><tr><td><p><b>H</b>ypo / <b>H</b>yperkalemia</p></td><td><p><b>HyperK+:</b> IV Calcium Chloride/Gluconate + Insulin/D50 + NaHCO3</p></td><td><p><b>T</b>hrombosis, <b>P</b>ulmonary (<b>Massive PE</b>)</p></td><td><p><mark class=\"hl rx\"><b>IV Thrombolysis (Alteplase)</b></mark> + prolonged CPR</p></td></tr><tr><td></td><td></td><td></td><td></td></tr><tr><td><p><b>H</b>ypothermia</p></td><td><p>Active internal/external rewarming</p></td><td><p><b>T</b>hrombosis, <b>C</b>oronary (<mark class=\"hl lab\"><b> MI</b></mark> )</p></td><td><p>Emergent <b>PCI</b> / Thrombolysis</p></td></tr></table><h3><b>4. Post-ROSC (Return of Spontaneous Circulation) Care</b></h3><ul>\n<li class=\"l1\">Optimize oxygenation (<mark class=\"hl mech\"><b> SpO2 92–98%</b></mark> — avoid hyperoxia!), maintain <b>MAP ≥ 65 mmHg</b>, obtain <mark class=\"hl mech\"><b>12-Lead ECG</b></mark> immediately (urgent PCI if STEMI!), <b>Targeted Temperature Management</b> (prevent fever &lt; 37.5°C / 32–36°C if comatose).</li>\n</ul>\n<p class=\"muted\"><i>End of Part 4B — Cardiology (30 Cases Complete!)</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u79\">← Case 29</button></nav></article>"});
